      planIDs: {\n                [PLANS.VPN]: 1,\n            },\n            cycle: CYCLE.THIRTY,\n            couponCode: COUPON_CODES.VPN_BLACK_FRIDAY_2022,\n            features: getVPNPlusFeatures,\n            popular: true,\n            header: LifetimeDeal,\n        },\n        {\n            ref: 'bf_22_vpn_free-plus-1m-modal-u24',\n            planName: PLANS.BUNDLE,\n            planIDs: {\n                [PLANS.BUNDLE]: 1,\n            },\n            star: '1',\n            cycle: CYCLE.TWO_YEARS,\n            couponCode: COUPON_CODES.MAIL_BLACK_FRIDAY_2022,\n            features: getUnlimitedVPNFeatures,\n        },\n    ],\n    layout: Layout,\n};\n\nexport default config;\n","import { c } from 'ttag';\n\nimport { Tooltip } from '../../../../components';\n\nconst LifetimeDeal = () => {\n    return (\n        <Tooltip\n            title={c('specialoffer: Label')\n                .t`The discount will continue to apply upon renewal until the subscription is canceled or modified`}\n        >\n            <span>{c('specialoffer: Label').t`Lifetime deal`}</span>\n        </Tooltip>\n    );\n};\n\nexport default LifetimeDeal;\n","import { fromUnixTime, isBefore } from 'date-fns';\n\nimport { APPS, CYCLE, PLANS } from '@proton/shared/lib/constants';\nimport { getPlan, hasBlackFridayDiscount, isExternal, isTrial } from '@proton/shared/lib/helpers/subscription';\nimport { ProtonConfig, Subscription, UserModel } from '@proton/shared/lib/interfaces';\n\nimport { FREE_DOWNGRADER_LIMIT } from '../../helpers/offerPeriods';\n\ninterface Props {\n    user: UserModel;\n    subscription?: Subscription;\n    protonConfig: ProtonConfig;\n    lastSubscriptionEnd?: number;\n}\n\nconst isEligible = ({ user, subscription, protonConfig, lastSubscriptionEnd = 0 }: Props) => {\n    const plan = getPlan(subscription);\n    const noBF = !hasBlackFridayDiscount(subscription);\n    const isVpnApp = protonConfig.APP_NAME === APPS.PROTONVPN_SETTINGS;\n    return (\n        ((user.isFree && isBefore(fromUnixTime(lastSubscriptionEnd), FREE_DOWNGRADER_LIMIT)) ||\n            isTrial(subscription) ||\n            (plan?.Name === PLANS.VPN && subscription?.Cycle === CYCLE.MONTHLY && !user.hasPaidMail)) &&\n        noBF &&\n        user.canPay &&\n        isVpnApp &&\n        !user.isDelinquent &&\n        !isExternal(subscription)\n    );\n};\n\nexport default isEligible;\n","import { useConfig, useLastSubscriptionEnd, useSubscription, useUser } from '@proton/components/hooks';\n\nimport useOfferFlags from '../../hooks/useOfferFlags';\nimport { Operation } from '../../interface';\nimport config from './configuration';\nimport isEligible from './eligibility';\n\nconst useOffer = (): Operation => {\n    const [user, userLoading] = useUser();\n    const [subscription, loadingSubscription] = useSubscription();\n    const [lastSubscriptionEnd, lastSubscriptionEndLoading] = useLastSubscriptionEnd();\n    const { isActive, loading: flagsLoading } = useOfferFlags(config);\n    const protonConfig = useConfig();\n    const isLoading = flagsLoading || userLoading || lastSubscriptionEndLoading || loadingSubscription;\n    const isValid = isEligible({ user, protonConfig, subscription, lastSubscriptionEnd }) && isActive;\n\n    return { isValid, config, isLoading };\n};\n\nexport default useOffer;\n","import { c } from 'ttag';\n\nimport { ButtonLike } from '@proton/atoms';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { getOrganizationKeyInfo } from '@proton/shared/lib/organization/helper';\n\nimport { Alert, Block, LearnMore, SettingsLink } from '../../components';\nimport { useOrganization, useOrganizationKey } from '../../hooks';\nimport { getActivationText } from './helper';\n\nconst RestoreAdministratorPrivileges = () => {\n    const [organization, loadingOrganization] = useOrganization();\n    const [organizationKey, loadingOrganizationKey] = useOrganizationKey(organization);\n\n    const organizationKeyInfo = getOrganizationKeyInfo(organization, organizationKey);\n\n    if (loadingOrganization || loadingOrganizationKey || !organization?.HasKeys) {\n        return null;\n    }\n\n    if (organizationKeyInfo.userNeedsToReactivateKey) {\n        return (\n            <Block>\n                <Alert className=\"mb1\" type=\"error\">\n                    <div>\n                        {c('Restore administrator panel')\n                            .t`Due to a password change, your organization administrator privileges have been restricted. The following actions are no longer permitted:`}\n                    </div>\n                    <ul className=\"mb0\">\n                        <li>{c('Restore administrator panel').t`Creating new users`}</li>\n                        <li>{c('Restore administrator panel').t`Reading emails of non-private users`}</li>\n                        <li>{c('Restore administrator panel').t`Changing organization password`}</li>\n                        <li>{c('Restore administrator panel').t`Changing organization keys`}</li>\n                    </ul>\n                </Alert>\n                <ButtonLike as={SettingsLink} path=\"/organization-keys\" color=\"norm\" className=\"mr1\">\n                    {c('Action').t`Restore administrator privileges`}\n                </ButtonLike>\n                <LearnMore className=\"inline-block\" url={getKnowledgeBaseUrl('/proton-for-business')} />\n            </Block>\n        );\n    }\n\n    if (organizationKeyInfo.userNeedsToActivateKey) {\n        return (\n            <Block>\n                <Alert className=\"mb1\" type=\"error\">\n                    {getActivationText()}\n                </Alert>\n                <ButtonLike as={SettingsLink} path=\"/organization-keys\" color=\"norm\">\n                    {c('Action').t`Activate organization key`}\n                </ButtonLike>\n            </Block>\n        );\n    }\n\n    return null;\n};\n\nexport default RestoreAdministratorPrivileges;\n","import { c } from 'ttag';\n\nexport const getActivationText = () => {\n    return c('Error')\n        .t`You must activate your organization keys. Without activation you will not be able to create new users, add addresses to existing users, or access non-private user accounts.`;\n};\n","import { c, msgid } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { BRAND_NAME, VPN_APP_NAME } from '@proton/shared/lib/constants';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport { AlertModal, ModalProps } from '../../components';\n\ninterface Props extends ModalProps {\n    organization: Organization;\n    onConfirm: () => void;\n}\n\nconst LossLoyaltyModal = ({ organization, onConfirm, onClose, ...rest }: Props) => {\n    const bonusSpace = organization.BonusSpace && humanSize(organization.BonusSpace, 'GB');\n\n    return (\n        <AlertModal\n            title={c('Title').t`Confirm loss of ${BRAND_NAME} bonuses`}\n            buttons={[\n                <Button\n                    onClick={() => {\n                        onConfirm();\n                        onClose?.();\n                    }}\n                    color=\"danger\"\n                >\n                    {c('Action').t`Remove bonuses`}\n                </Button>,\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            onClose={onClose}\n            {...rest}\n        >\n            <div className=\"mb1\">\n                {c('Info').t`Since you're a loyal user, your account has additional features enabled.`}\n            </div>\n            <div>\n                {c('Info')\n                    .t`By downgrading to a Free plan, you will permanently lose these benefits, even if you upgrade again in the future.`}\n                <ul>\n                    {organization.BonusSpace ? <li>{c('Info').t`+${bonusSpace} bonus storage`}</li> : null}\n                    {organization.BonusVPN ? (\n                        <li>\n                            {c('Info').ngettext(\n                                msgid`+${organization.BonusVPN} connection for ${VPN_APP_NAME} (allows you to connect more devices to VPN)`,\n                                `+${organization.BonusVPN} connections for ${VPN_APP_NAME} (allows you to connect more devices to VPN)`,\n                                organization.BonusVPN\n                            )}\n                        </li>\n                    ) : null}\n                </ul>\n            </div>\n        </AlertModal>\n    );\n};\n\nexport default LossLoyaltyModal;\n","import { FormEvent, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button, Card } from '@proton/atoms';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { Organization } from '@proton/shared/lib/interfaces';\n\nimport {\n    Form,\n    InputFieldTwo,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n    useFormErrors,\n} from '../../components';\n\ninterface Props extends ModalProps {\n    organization: Organization;\n    onConfirm: () => void;\n}\n\nconst MemberDowngradeModal = ({ organization, onConfirm, onClose, ...rest }: Props) => {\n    const { validator, onFormSubmit } = useFormErrors();\n    const [confirmText, setConfirmText] = useState('');\n    const organizationName = organization.Name;\n\n    return (\n        <Modal\n            as={Form}\n            onSubmit={(event: FormEvent) => {\n                event.preventDefault();\n                if (!onFormSubmit()) {\n                    return;\n                }\n                onConfirm();\n                onClose?.();\n            }}\n            onClose={onClose}\n            {...rest}\n        >\n            <ModalHeader title={c('Title').t`Delete organization?`} />\n            <ModalContent>\n               