/AppLink>\n    );\n\n    const title = isDowngrade ? c('Title').t`Downgrade account` : c('Title').t`Cancel Mail subscription`;\n    const text = isDowngrade\n        ? c('Info')\n              .t`You must remove any additional personal calendars and any shared calendar links before you can cancel your subscription.`\n        : c('Info')\n              .t`You must remove any additional personal calendars and any shared calendar links before you can cancel your Mail subscription.`;\n\n    return (\n        <AlertModal\n            title={title}\n            buttons={[\n                <Button\n                    onClick={() => {\n                        onConfirm();\n                        onClose?.();\n                    }}\n                    color=\"norm\"\n                >\n                    {c('Action').t`OK`}\n                </Button>,\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            onClose={onClose}\n            {...rest}\n        >\n            <div>\n                {text}\n                <br />\n                {linkButton}\n            </div>\n        </AlertModal>\n    );\n};\n\nexport default CalendarDowngradeModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { BRAND_NAME } from '@proton/shared/lib/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { AlertModal, AlertModalProps, Href } from '../../../components';\n\ninterface Props extends Omit<AlertModalProps, 'children' | 'title' | 'buttons'> {\n    onConfirm: () => void;\n}\n\nexport const NewVisionaryWarningModal = ({\n    onConfirm,\n    type,\n    ...rest\n}: Props & { type: 'downgrade' | 'switch' | 'delete' }) => {\n    const visionary = 'Visionary';\n    const plan = 'visionary';\n    return (\n        <AlertModal\n            title={(() => {\n                if (type === 'switch') {\n                    return c('new_plans: title').t`Switch plans?`;\n                }\n                if (type === 'delete') {\n                    return c('new_plans: title').t`Delete account?`;\n                }\n                if (type === 'downgrade') {\n                    return c('new_plans: title').t`Downgrade account?`;\n                }\n                return '';\n            })()}\n            buttons={[\n                <Button color=\"norm\" onClick={rest.onClose}>\n                    {(() => {\n                        if (type === 'switch') {\n                            return c('new_plans: action').t`Keep ${plan}`;\n                        }\n                        if (type === 'downgrade') {\n                            return c('new_plans: action').t`Keep account`;\n                        }\n                        if (type === 'delete') {\n                            return c('new_plans: action').t`Keep account`;\n                        }\n                        return '';\n                    })()}\n                </Button>,\n                <Button\n                    onClick={() => {\n                        onConfirm();\n                        rest.onClose?.();\n                    }}\n                >\n                    {(() => {\n                        if (type === 'switch') {\n                            return c('new_plans: action').t`Switch plan`;\n                        }\n                        if (type === 'downgrade') {\n                            return c('new_plans: action').t`Downgrade account`;\n                        }\n                        if (type === 'delete') {\n                            return c('new_plans: action').t`Delete account`;\n                        }\n                        return '';\n                    })()}\n                </Button>,\n            ]}\n            {...rest}\n        >\n            {c('new_plans: info')\n                .t`Our ${visionary} plan is no longer available to new subscribers as it is a special plan for original ${BRAND_NAME} users with special features and benefits.`}{' '}\n            {(() => {\n                if (type === 'switch') {\n                    return c('new_plans: info')\n                        .t`If you switch to a different plan, you lose all ${visionary} plan benefits and won’t be able to switch back to ${visionary}.`;\n                }\n                if (type === 'downgrade') {\n                    return c('new_plans: info')\n                        .t`If you downgrade your account, you lose all ${visionary} plan benefits and it won’t be available if you try to subscribe again.`;\n                }\n                if (type === 'delete') {\n                    return c('new_plans: info')\n                        .t`If you delete your account, you lose all ${visionary} plan benefits and it won’t be available if you create a new account.`;\n                }\n            })()}{' '}\n            <Href url={getKnowledgeBaseUrl('/upgrading-to-new-proton-plan/#switch-from-visionary')}>{c('Info')\n                .t`Learn more`}</Href>\n        </AlertModal>\n    );\n};\n\nexport const DiscountWarningModal = ({ onConfirm, type, ...rest }: Props & { type: 'downgrade' | 'delete' }) => {\n    return (\n        <AlertModal\n            title={(() => {\n                if (type === 'delete') {\n                    return c('new_plans: title').t`Delete account?`;\n                }\n                return c('new_plans: title').t`Downgrade account?`;\n            })()}\n            buttons={[\n                <Button color=\"norm\" onClick={rest.onClose}>\n                    {(() => {\n                        if (type === 'delete') {\n                            return c('new_plans: action').t`Keep account`;\n                        }\n                        return c('new_plans: action').t`Keep account`;\n                    })()}\n                </Button>,\n                <Button\n                    onClick={() => {\n                        onConfirm();\n                        rest.onClose?.();\n                    }}\n                >\n                    {(() => {\n                        if (type === 'delete') {\n                            return c('new_plans: action').t`Delete account`;\n                        }\n                        return c('new_plans: action').t`Downgrade account`;\n                    })()}\n                </Button>,\n            ]}\n            {...rest}\n        >\n            {(() => {\n                if (type === 'delete') {\n                    return c('new_plans: info')\n                        .t`You’re enjoying a promotional price on your current plan. If you delete your account, you will lose your promotional price and it won’t be available if you create a new account.`;\n                }\n                return c('new_plans: info')\n                    .t`You’re enjoying a promotional price on your current plan. If you downgrade your account, you will lose your promotional price and it won’t be available if you try to subscribe again.`;\n            })()}\n        </AlertModal>\n    );\n};\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { CYCLE, DEFAULT_CYCLE } from '@proton/shared/lib/constants';\nimport { Cycle } from '@proton/shared/lib/interfaces';\n\nimport { ButtonGroup, Option, SelectTwo } from '../../components';\nimport Select, { Props as SelectProps } from '../../components/select/Select';\nimport { classnames } from '../../helpers';\n\nconst { MONTHLY, YEARLY, TWO_YEARS } = CYCLE;\n\ninterface Props extends Omit<SelectProps, 'onSelect' | 'onChange' | 'options'> {\n    cycle: Cycle;\n    onSelect: (newCycle: Cycle) => void;\n    options?: SelectProps['options'];\n    mode?: 'buttons' | 'select' | 'select-two';\n    disabled?: boolean;\n}\n\nconst CycleSelector = ({\n    cycle = DEFAULT_CYCLE,\n    mode = 'select',\n    disabled,\n    onSelect,\n    options = [\n        { text: c('Billing cycle option').t`Monthly`, value: MONTHLY },\n        { text: c('Billing cycle option').t`Annually`, value: YEARLY },\n        { text: c('Billing cycle option').t`Two-year`, value: TWO_YEARS },\n    ],\n    ...rest\n}: Props) => {\n    if (mode === 'buttons') {\n        return (\n            <ButtonGroup>\n                {options.map(({ text, value }) => {\n                    // translator: this text is only for screen readers, \"Billing cycle: ${text}\" (${text} contains: \"1 month\", \"12 months\" or \"24 months\")\n                    const billingCycleVocalizedText = c('Info').t`Billing cycle: ${text}`;\n                    const isSelected = cycle === value;\n\n                    return (\n                        <Button\n                            className={classnames([isSelected && 'is-selected'])}\n                            key={value}\n                            onClick={() => onSelect(value as Cycle)}\n                            disabled={disabled}\n                            aria-label={billingCycleVocalizedText}\n                            aria-pressed={isSelected}\n                        >\n                            {text}\n                        </Button>\n                    );\n                })}\n            </ButtonGroup>\n        );\n    }\n    if (mode === 'select-two') {\n        const handleChange = ({ value }: { value: Cycle }) => onSelect(value);\n        return (\n            <SelectTwo value={cycle} onChange={handleChange} disabled={disabled}>\n                {options.map(({ text, value }) => {\n                    return (\n                        <Option value={value} title={`${text}`}>\n                            {text}\n                        </Option>\n                    );\n                })}\n            </SelectTwo>\n        );\n    }\n    return (\n        <Select\n            title={c('Title').t`Billing cycle`}\n            value={cycle}\n            options={options}\n            onChange={({ target }) => onSelect(+target.value as Cycle)}\n            {...rest}\n        />\n    );\n};\n\nexport default CycleSelector;\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { PLANS } from '@proton/shared/lib/constants';\nimport { Currency, Cycle } from '@proton/shared/lib/interfaces';\n\nimport { Badge, Icon, Price, PrimaryButton } from '../../../components';\nimport { classnames } from '../../../helpers';\n\ninterface Props {\n    planName: PLANS;\n    planTitle: ReactNode;\n    price: number;\n    info: string;\n    action: string;\n    onSelect: (planName: PLANS) => void;\n    features: ReactNode;\n    currency: Currency;\n    cycle: Cycle;\n    isCurrentPlan?: boolean;\n    disabled?: boolean;\n    recommended?: boolean;\n    canSelect?: boolean;\n}\n\nconst getCycleUnit = (planName: PLANS) => {\n    switch (planName) {\n        case PLANS.FREE:\n            return '';\n        case PLANS.MAIL_PRO:\n        case PLANS.DRIVE_PRO:\n        case PLANS.BUNDLE_PRO:\n        case PLANS.ENTERPRISE:\n            return c('Cycle').t`/user per month`;\n        default:\n            return c('Cycle').t`/month`;\n    }\n};\n\nconst PlanCard = ({\n    planName,\n    planTitle,\n    price,\n    info,\n    action,\n    onSelect,\n    features,\n    currency,\n    cycle,\n    disabled,\n    isCurrentPlan,\n    recommended,\n}: Props) => {\n    const badgeMultiUser = planName === PLANS.FAMILY ? <Badge type=\"success\">{c('Badge').t`5 users`}</Badge> : null;\n\n    return (\n        <>\n            <div\n                className={classnames([\n                    'border relative h100 plan-selection-plan p2 pb0 flex flex-column flex-nowrap',\n                    isCurrentPlan && 'plan-selection-plan-current-card',\n                    recommended && 'plan-selection-plan-recommended border-primary',\n                ])}\n            >\n                {recommended ? (\n                    <div className=\"plan-selection-plan-recommended-pill-container text-aligncenter flex\">\n                        <div className=\"plan-selection-plan-recommended-pill inline-flex mlauto mrauto flex-items-align-center bg-primary p0-25 pl0-75 pr0-75\">\n                            <Icon name=\"star-filled\" className=\"myauto\" />\n                            <span className=\"ml0-25\">{c('Title').t`Recommended`}</span>\n                        </div>\n                    </div>\n                ) : null}\n                <div className=\"flex flex-row flex-align-items-center\">\n                    <h2\n                        className=\"h3 plan-selection-title flex text-bold text-capitalize mb0-5\"\n                        id={`desc_${planName}`}\n                    >\n                        {planTitle}\n                    </h2>\n                    <span className=\"ml0-5 mb0-5\">{badgeMultiUser}</span>\n                </div>\n                <p className=\"text-lg plan-selection-info text-left color-weak mb1\">{info}</p>\n                <div className=\"mb1 flex flex-wrap flex-align-items-baseline plan-selection-price\">\n                    <span className=\"mr0-5\">\n                        <Price large currency={currency}>\n                            {price / cycle}\n                        </Price>\n                    </span>\n                    <span className=\"color-weak plan-selection-suffix\">{getCycleUnit(planName)}</span>\n                </div>\n\n                <PrimaryButton\n                    onClick={() => onSelect(planName)}\n                    disabled={disabled}\n                    className=\"w100\"\n                    aria-describedby={`desc_${planName}`}\n                >\n                    {action}\n                </PrimaryButton>\n                <div className=\"flex flex-column flex-nowrap flex-item-fluid-auto mt0-5\">{features}</div>\n            </div>\n        </>\n    );\n};\n\nexport default PlanCard;\n","import { c } from 'ttag';\n\nimport { CYCLE, PLANS, PLAN_TYPES } from '@proton/shared/lib/constants';\nimport { switchPlan } from '@proton/shared/lib/helpers/planIDs';\nimport {\n    Audience,\n    Currency,\n    Cycle,\n    Organization,\n    Plan,\n    PlanIDs,\n    PlansMap,\n    Subscription,\n    VPNCountries,\n    VPNServers,\n} from '@proton/shared/lib/interfaces';\nimport { FREE_PLAN } from '@proton/shared/lib/subscription/freePlans';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { CalendarLogo, DriveLogo, Icon, MailLogo, Option, SelectTwo, Tabs, VpnLogo } from '../../../components';\nimport CurrencySelector from '../CurrencySelector';\nimport CycleSelector from '../CycleSelector';\nimport { getAllFeatures } from '../features';\nimport { getShortPlan } from '../features/plan';\nimport PlanCard from './PlanCard';\nimport PlanCardFeatures, { PlanCardFeaturesShort } from './PlanCardFeatures';\n\nimport './PlanSelection.scss';\n\nexport interface SelectedProductPlans {\n    [Audience.B2C]: PLANS;\n    [Audience.B2B]: PLANS;\n}\n\nconst getPlansList = (enabledProductPlans: PLANS[], plansMap: PlansMap) => {\n    return enabledProductPlans\n        .map((planName) => {\n            const plan = plansMap[planName];\n            if (plan) {\n                return {\n                    planName,\n                    label: plan.Title,\n                };\n            }\n        })\n        .filter(isTruthy);\n};\n\nconst getPlanPanel = (enabledProductPlans: PLANS[], planName: PLANS, plansMap: PlansMap) => {\n    if (enabledProductPlans.includes(planName)) {\n        return plansMap[planName];\n    }\n};\n\ninterface Props {\n    planIDs: PlanIDs;\n    currency: Currency;\n    hasPlanSelectionComparison?: boolean;\n    hasFreePlan?: boolean;\n    cycle: Cycle;\n    plans: Plan[];\n    plansMap: PlansMap;\n    vpnServers: VPNServers;\n    vpnCountries: VPNCountries;\n    loading?: boolean;\n    mode: 'signup' | 'settings' | 'modal';\n    onChangePlanIDs: (newPlanIDs: PlanIDs) => void;\n    onChangeCurrency: (newCurrency: Currency) => void;\n    onChangeCycle: (newCyle: Cycle) => void;\n    audience: Audience;\n    onChangeAudience: (newAudience: Audience) => void;\n    selectedProductPlans: SelectedProductPlans;\n    onChangeSelectedProductPlans: (newPlans: SelectedProductPlans) => void;\n    subscription?: Subscription;\n    organization?: Organization;\n}\n\nconst PlanSelection = ({\n    mode,\n    hasFreePlan = true,\n    planIDs,\n    plans,\n    plansMap,\n    vpnServers,\n    vpnCountries,\n    cycle,\n    currency,\n    loading,\n    subscription,\n    organization,\n    onChangePlanIDs,\n    onChangeCurrency,\n    onChangeCycle,\n    audience,\n    onChangeAudience,\n    selectedProductPlans,\n    onChangeSelectedProductPlans,\n}: Props) => {\n    const currentPlan = subscription ? subscription.Plans?.find(({ Type }) => Type === PLAN_TYPES.PLAN) : null;\n\n    const enabledProductB2CPlans = [PLANS.MAIL, PLANS.VPN, PLANS.DRIVE];\n    const enabledProductB2BPlans = [PLANS.MAIL_PRO /*, PLANS.DRIVE_PRO*/];\n\n    const B2CPlans = [\n        hasFreePlan ? FREE_PLAN : null,\n        getPlanPanel(enabledProductB2CPlans, selectedProductPlans[Audience.B2C], plansMap) || plansMap[PLANS.MAIL],\n        plansMap[PLANS.BUNDLE],\n    ].filter(isTruthy);\n\n    const B2BPlans = [\n        hasFreePlan ? FREE_PLAN : null,\n        getPlanPanel(enabledProductB2BPlans, selectedProductPlans[Audience.B2B], plansMap) || plansMap[PLANS.MAIL_PRO],\n        plansMap[PLANS.BUNDLE_PRO],\n    ].filter(isTruthy);\n\n    const isSignupMode = mode === 'signup';\n    const features = getAllFeatures(plansMap, vpnCountries, vpnServers);\n\n    const plansListB2C = getPlansList(enabledProductB2CPlans, plansMap);\n    const recommendedPlans = [PLANS.BUNDLE, PLANS.BUNDLE_PRO];\n\n    const renderPlanCard = (plan: Plan, audience: Audience) => {\n        const isFree = plan.ID === PLANS.FREE;\n        const isCurrentPlan = isFree ? !currentPlan : currentPlan?.ID === plan.ID;\n        const isRecommended = recommendedPlans.includes(plan.Name as PLANS);\n        const shortPlan = getShortPlan(plan.Name as PLANS, plansMap, vpnCountries, vpnServers);\n\n        if (!shortPlan) {\n            return null;\n        }\n\n        const planTitle = shortPlan.title;\n        const selectedPlanLabel = isFree ? c('Action').t`Current plan` : c('Action').t`Edit subscription`;\n        const actionLabel = isCurrentPlan ? selectedPlanLabel : c('Action').t`Select ${planTitle}`;\n\n        const plansList = audience === Audience.B2C ? plansListB2C : [];\n        const isSelectable = plansList.some(({ planName: otherPlanName }) => otherPlanName === plan.Name);\n        const selectedPlan = plansList.some(\n            ({ planName: otherPlanName }) => otherPlanName === selectedProductPlans[audience]\n        )\n            ? selectedProductPlans[audience]\n            : plansList[0]?.planName;\n\n        const price = plan.Pricing[cycle];\n        if (price === undefined) {\n            return null;\n        }\n\n        return (\n            <PlanCard\n                isCurrentPlan={!isSignupMode && isCurrentPlan}\n                action={actionLabel}\n                info={shortPlan.description}\n                planName={plan.Name as PLANS}\n                planTitle={\n                    plansList && isSelectable ? (\n                        <SelectTwo\n                            value={selectedPlan}\n                            onChange={({ value: newPlanName }) => {\n                                onChangeSelectedProductPlans({ ...selectedProductPlans, [audience]: newPlanName });\n                            }}\n                        >\n                            {plansList.map(({ planName, label }) => (\n                                <Option key={label} value={planName} title={label}>\n                                    {label}\n                                </Option>\n                            ))}\n                        </SelectTwo>\n                    ) : (\n                        planTitle\n                    )\n                }\n                recommended={isRecommended}\n                currency={currency}\n                disabled={loading || (isFree && !isSignupMode && isCurrentPlan)}\n                cycle={cycle}\n                key={plan.ID}\n                price={price}\n                features={\n                    mode === 'settings' ? (\n                        <PlanCardFeaturesShort plan={shortPlan} icon />\n                    ) : (\n                        <PlanCardFeatures audience={audience} features={features} planName={plan.Name as PLANS} />\n                    )\n                }\n                onSelect={(planName) => {\n                    onChangePlanIDs(\n                        switchPlan({\n                            planIDs,\n                            planID: isFree ? undefined : planName,\n                            organization,\n                            plans,\n                        })\n                    );\n                }}\n            />\n        );\n    };\n\n    const tabs = [\n        {\n            title: c('Tab subscription modal').t`For individuals`,\n            content: (\n                <div\n                    className=\"plan-selection plan-selection--b2c mt1\"\n                    style={{ '--plan-selection-number': B2CPlans.length }}\n                >\n                    {B2CPlans.map((plan) => renderPlanCard(plan, Audience.B2C))}\n                </div>\n            ),\n        },\n        {\n            title: c('Tab subscription modal').t`For businesses`,\n            content: (\n                <div\n                    className=\"plan-selection plan-selection--b2b mt1\"\n                    style={{ '--plan-selection-number': B2BPlans.length }}\n                >\n                    {B2BPlans.map((plan) => renderPlanCard(plan, Audience.B2B))}\n                </div>\n            ),\n        },\n    ];\n\n    const currencyItem = (\n        <CurrencySelector mode=\"select-two\" currency={currency} onSelect={onChangeCurrency} disabled={loading} />\n    );\n    const currencySelectorRow = (\n        <div className=\"flex flex-justify-space-between on-mobile-flex-column-nostretch\">\n            <div className=\"inline-block no-mobile visibility-hidden\">{currencyItem}</div>\n            <div className=\"flex on-mobile-flex on-mobile-flex-justify-center on-mobile-w100\">\n                <CycleSelector\n                    mode=\"buttons\"\n                    cycle={cycle}\n                    onSelect={onChangeCycle}\n                    disabled={loading}\n                    options={[\n                        { text: c('Billing cycle option').t`1 month`, value: CYCLE.MONTHLY },\n                        { text: c('Billing cycle option').t`12 months`, value: CYCLE.YEARLY },\n                        { text: c('Billing cycle option').t`24 months`, value: CYCLE.TWO_YEARS },\n                    ]}\n                />\n            </div>\n            <div className=\"flex on-mobile-center on-mobile-mt1\">{currencyItem}</div>\n        </div>\n    );\n\n    const logosRow = (\n        <div className=\"mt2 mb2 flex flex-justify-center flex-nowrap flex-align-items-center color-weak\">\n            <MailLogo />\n            <Icon name=\"plus\" alt=\"+\" className=\"mx0-5\" />\n            <CalendarLogo />\n            <Icon name=\"plus\" alt=\"+\" className=\"mx0-5\" />\n            <DriveLogo />\n            <Icon name=\"plus\" alt=\"+\" className=\"mx0-5\" />\n            <VpnLogo />\n        </div>\n    );\n\n    return (\n        <>\n            <div className=\"mb2\">\n                <Tabs\n                    value={audience === Audience.B2C ? 0 : 1}\n                    onChange={(newValue) => {\n                        onChangeAudience(newValue === 0 ? Audience.B2C : Audience.B2B);\n                    }}\n                    tabs={tabs}\n                    containerClassName=\"inline-block\"\n                    navContainerClassName=\"text-center\"\n                    gap={\n                        mode === 'settings' ? (\n                            <>\n                                {logosRow}\n                                {currencySelectorRow}\n                            </>\n                        ) : (\n                            <div className=\"mt1\">{currencySelectorRow}</div>\n                        )\n                    }\n                />\n            </div>\n        </>\n    );\n};\nexport default PlanSelection;\n","import { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport { Icon, Info, InputTwo, UnderlineButton } from '../../components';\nimport { useToggle } from '../../hooks';\n\ninterface Props {\n    loading?: boolean;\n    giftCode?: string;\n    onApply: (value: string) => void;\n}\n\nconst getFormattedGiftCode = (giftCode: string) => {\n    const splittedGiftCode = giftCode.replace(/-/g, '').match(/.{1,4}/g) || [''];\n    return splittedGiftCode.join('-').toUpperCase();\n};\n\nconst PaymentGiftCode = ({ giftCode = '', onApply, loading }: Props) => {\n    const { state, toggle, set } = useToggle();\n    const [code, setCode] = useState('');\n\n    const handleCancel = () => {\n        set(false);\n        setCode('');\n    };\n\n    useEffect(() => {\n        // When we remove the gift code\n        if (!giftCode) {\n            handleCancel();\n        }\n    }, [giftCode]);\n\n    if (giftCode) {\n        return (\n            <div className=\"flex flex-align-items-center\">\n                <span className=\"flex-item-fluid flex-nowrap flex-align-items-center\">\n                    <Icon name=\"gift\" className=\"mr0-5 mb0-25 flex-item-noshrink\" />\n                    <code>{getFormattedGiftCode(giftCode)}</code>\n                </span>\n                <Button\n                    icon\n                    shape=\"ghost\"\n                    className=\"flex flex-align-items-center ml0-25\"\n                    onClick={() => onApply('')}\n                    title={c('Action').t`Remove gift code`}\n                >\n                    <Icon name=\"trash\" alt={c('Action').t`Remove gift code`} />\n                </Button>\n            </div>\n        );\n    }\n\n    if (state) {\n        const handleSubmit = () => {\n            if (!code) {\n                return;\n            }\n            onApply(code);\n        };\n\n        return (\n            <div className=\"flex flex-nowrap flex-align-items-center flex-align-items-start\">\n                <div className=\"pr0-5 flex-item-fluid\">\n                    <InputTwo\n                        value={code}\n                        placeholder={c('Placeholder').t`Gift code`}\n                        onValue={setCode}\n                        onKeyDown={(event) => {\n                            if (event.key === 'Enter') {\n                                event.preventDefault();\n                                handleSubmit();\n                            }\n                        }}\n                    />\n                </div>\n                <Button\n                    color=\"norm\"\n                    title={c('Title').t`Apply gift code`}\n                    loading={loading}\n                    disabled={!code}\n                    onClick={handleSubmit}\n                >{c('Action').t`Apply`}</Button>\n            </div>\n        );\n    }\n\n    return (\n        <>\n            <UnderlineButton className=\"mr0-5\" onClick={toggle}>{c('Link').t`Add a gift code`}</UnderlineButton>\n            <Info\n                title={c('Tooltip')\n                    .t`If you purchased a gift code or received one from our support team, you can enter it here.`}\n            />\n        </>\n    );\n};\n\nexport default PaymentGiftCode;\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Currency } from '@proton/shared/lib/interfaces';\n\nimport { Icon } from '../../components';\nimport CurrencySelector from './CurrencySelector';\n\ninterface Props {\n    currency: Currency;\n    onChangeCurrency: (newCurrency: Currency) => void;\n    loading?: boolean;\n    children: ReactNode;\n    hasGuarantee?: boolean;\n    hasPayments?: boolean;\n    description?: ReactNode;\n}\n\nconst Checkout = ({\n    currency,\n    onChangeCurrency,\n    loading,\n    children,\n    hasGuarantee,\n    hasPayments = true,\n    description,\n}: Props) => {\n    return (\n        <div className=\"p2\">\n            <div className=\"flex flex-nowrap flex row mb1\">\n                <h2 className=\"h4 text-bold mt0-25 mb0 text-cut flex-item-fluid\">{c('Title').t`Plan summary`}</h2>\n                <span className=\"flex-item-noshrink\">\n                    <CurrencySelector\n                        currency={currency}\n                        onSelect={onChangeCurrency}\n                        className=\"\"\n                        mode=\"select-two\"\n                        disabled={loading}\n                    />\n                </span>\n            </div>\n\n            <div className={loading ? 'opacity-50 no-pointer-events-children' : ''}>{children}</div>\n            <div className=\"text-sm lh-standard\">\n                {hasPayments ? (\n                    <div className=\"flex flex-nowrap color-weak mb0-5 mt0-5\">\n                        <span className=\"flex-item-noshrink mr0-5\">\n                            <Icon name=\"shield\" />\n                        </span>\n                        <span className=\"flex-item-fluid\">{c('Info')\n                            .t`Payments are protected with TLS encryption and Swiss privacy laws.`}</span>\n                    </div>\n                ) : (\n                    <div className=\"flex flex-nowrap mb0-5\">\n                        <b className=\"flex-item-fluid\">{c('new_plans: info')\n                            .t`Applicable credits, proration, and coupons are applied in the next step`}</b>\n                    </div>\n                )}\n                {hasGuarantee && (\n                    <div className=\"flex flex-nowrap color-weak\">\n                        <span className=\"flex-item-noshrink mr0-5\">\n                            <Icon name=\"clock\" />\n                        </span>\n                        <span className=\"flex-item-fluid\">{c('Info').t`30-day money-back guarantee.`}</span>\n                    </div>\n                )}\n            </div>\n            {description}\n        </div>\n    );\n};\n\nexport default Checkout;\n","import { c } from 'ttag';\n\nimport { Info, Time } from '../../components';\n\nexport interface Props {\n    nextSubscriptionStart: number;\n}\n\nconst StartDateCheckoutRow = ({ nextSubscriptionStart }: Props) => {\n    const formattedTime = <Time key=\"time-text\">{nextSubscriptionStart}</Time>;\n\n    return (\n        <div className=\"flex flex-nowrap flex-justify-space-between mb1\">\n            <div className=\"pr0-5\">\n                {c('Label').t`Start date`}{' '}\n                <Info title={c('Tooltip').jt`The new subscription cycle starts on ${formattedTime}`} />\n            </div>\n            {formattedTime}\n        </div>\n    );\n};\n\nexport default StartDateCheckoutRow;\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Currency } from '@proton/shared/lib/interfaces';\n\nimport { Price } from '../../../components';\nimport { classnames } from '../../../helpers';\n\ninterface Props {\n    title: ReactNode;\n    amount: number;\n    currency?: Currency;\n    className?: string;\n    suffix?: string;\n}\n\nconst CheckoutRow = ({ title, amount = 0, currency, className = '', suffix }: Props) => {\n    if (amount === 0 && !currency) {\n        return (\n            <div className={classnames(['flex flex-nowrap flex-justify-space-between mb1', className])}>\n                <div className=\"pr0-5\">{title}</div>\n                <span>{c('Price').t`Free`}</span>\n            </div>\n        );\n    }\n    return (\n        <div className={classnames(['flex flex-nowrap flex-justify-space-between mb1', className])}>\n            <div className=\"pr0-5\">{title}</div>\n            <Price currency={currency} suffix={suffix}>\n                {amount}\n            </Price>\n        </div>\n    );\n};\n\nexport default CheckoutRow;\n","import { ReactNode } from 'react';\n\nimport { c } from 'ttag';\n\nimport { APPS, PLANS } from '@proton/shared/lib/constants';\nimport {\n    Included,\n    RequiredCheckResponse,\n    getCheckout,\n    getDiscountText,\n    getWhatsIncluded,\n} from '@proton/shared/lib/helpers/checkout';\nimport { hasPlanIDs } from '@proton/shared/lib/helpers/planIDs';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Currency, Cycle, PlanIDs, PlansMap, VPNServers } from '@proton/shared/lib/interfaces';\n\nimport {\n    Badge,\n    Collapsible,\n    CollapsibleContent,\n    CollapsibleHeader,\n    CollapsibleHeaderIconButton,\n    Icon,\n    Info,\n} from '../../../components';\nimport { useConfig } from '../../../hooks';\nimport Checkout from '../Checkout';\nimport StartDateCheckoutRow from '../StartDateCheckoutRow';\nimport { getTotalBillingText } from '../helper';\nimport CheckoutRow from './CheckoutRow';\n\nconst PlanDescription = ({ list }: { list: Included[] }) => {\n    return (\n        <div className=\"mt2\">\n            <hr />\n            <Collapsible>\n                <CollapsibleHeader\n                    className=\"text-semibold\"\n                    suffix={\n                        <CollapsibleHeaderIconButton>\n                            <Icon name=\"chevron-down\" />\n                        </CollapsibleHeaderIconButton>\n                    }\n                >\n                    {c('Action').t`What do I get?`}\n                </CollapsibleHeader>\n                <CollapsibleContent>\n                    {list.map((item) => {\n                        if (item.type === 'value') {\n                            return (\n                                <div key={`${item.text}${item.type}`} className=\"flex flex-nowrap mb0-5\">\n                                    <div className=\"flex-item-fluid-auto text-ellipsis mr1\">{item.text}</div>\n                                    <div className=\"flex-item-fluid-auto flex-item-noshrink text-right\">\n                                        {item.value}\n                                    </div>\n                                </div>\n                            );\n                        }\n                        if (item.type === 'text') {\n                            return (\n                                <div key={`${item.text}${item.type}`} className=\"flex flex-nowrap mb0-5\">\n                                    <div className=\"flex-item-fluid-auto text-ellipsis\">{item.text}</div>\n                                </div>\n                            );\n                        }\n                        return null;\n                    })}\n                </CollapsibleContent>\n            </Collapsible>\n        </div>\n    );\n};\n\ninterface Props {\n    submit?: ReactNode;\n    loading?: boolean;\n    plansMap: PlansMap;\n    vpnServers: VPNServers;\n    checkResult: RequiredCheckResponse | undefined;\n    currency: Currency;\n    cycle: Cycle;\n    gift?: ReactNode;\n    onChangeCurrency: (currency: Currency) => void;\n    planIDs: PlanIDs;\n    isOptimistic?: boolean;\n    showProration?: boolean;\n    nextSubscriptionStart?: number;\n}\n\nconst SubscriptionCheckout = ({\n    submit = c('Action').t`Pay`,\n    plansMap,\n    vpnServers,\n    currency,\n    cycle,\n    onChangeCurrency,\n    gift,\n    isOptimistic,\n    planIDs,\n    checkResult,\n    loading,\n    showProration,\n    nextSubscriptionStart,\n}: Props) => {\n    const { APP_NAME } = useConfig();\n    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;\n    const { planTitle, usersTitle, discountPercent, withDiscountPerMonth, withDiscountPerCycle, addons } = getCheckout({\n        planIDs,\n        plansMap,\n        checkResult,\n    });\n\n    if (!checkResult) {\n        return null;\n    }\n\n    const isFreePlanSelected = !hasPlanIDs(planIDs);\n    const isVPNPlanSelected = !!planIDs?.[PLANS.VPN];\n\n    const proration = Math.abs(checkResult.Proration || 0);\n    const credit = Math.abs(checkResult.Credit || 0);\n    const amount = checkResult.Amount || 0;\n    const amountDue = checkResult.AmountDue || 0;\n    const giftValue = Math.abs(checkResult.Gift || 0);\n\n    const list = getWhatsIncluded({ planIDs, plansMap, vpnServers });\n\n    const displayProration = showProration ?? true;\n    const displayStartDate = !displayProration;\n\n    return (\n        <Checkout\n            currency={currency}\n            onChangeCurrency={onChangeCurrency}\n            loading={loading}\n            hasGuarantee={isVPNPlanSelected}\n            hasPayments={!isOptimistic}\n            description={<PlanDescription list={list} />}\n        >\n            <div className=\"mb1\">\n                <strong>{planTitle}</strong>\n            </div>\n            <CheckoutRow\n                title={\n                    <>\n                        {usersTitle}\n                        {discountPercent > 0 && (\n                            <Badge type=\"success\" tooltip={getDiscountText()} className=\"ml0-5 text-semibold\">\n                                -{discountPercent}%\n                            </Badge>\n                        )}\n                    </>\n                }\n                amount={withDiscountPerMonth}\n                currency={currency}\n                suffix={c('Suffix').t`/month`}\n            />\n            {addons.map((addon) => {\n                return (\n                    <div className=\"mb1\" key={addon.name}>\n                        {addon.title}\n                    </div>\n                );\n            })}\n            {!isFreePlanSelected && (\n                <>\n                    <div className=\"mb1\">\n                        <hr />\n                    </div>\n                    <CheckoutRow\n                        className=\"text-semibold\"\n                        title={<span className=\"mr0-5\">{getTotalBillingText(cycle)}</span>}\n                        amount={withDiscountPerCycle}\n                        currency={currency}\n                    />\n                </>\n            )}\n            {displayProration && proration > 0 && (\n                <CheckoutRow\n                    title={\n                        <span className=\"inline-flex flex-align-items-center\">\n                            <span className=\"mr0-5\">{c('Label').t`Proration`}</span>\n                            <Info\n                                title={c('Info').t`Credit for the unused portion of your previous plan subscription`}\n                                url={\n                                    isVPN\n                                        ? 'https://protonvpn.com/support/vpn-credit-proration/'\n                                        : getKnowledgeBaseUrl('/credit-proration-coupons')\n                                }\n                            />\n                        </span>\n                    }\n                    amount={-proration}\n                    currency={currency}\n                />\n            )}\n            {displayStartDate && nextSubscriptionStart && (\n                <StartDateCheckoutRow nextSubscriptionStart={nextSubscriptionStart} />\n            )}\n            {credit > 0 && <CheckoutRow title={c('Title').t`Credits`} amount={-credit} currency={currency} />}\n            {giftValue > 0 && <CheckoutRow title={c('Title').t`Gift`} amount={-giftValue} currency={currency} />}\n            {!isOptimistic && (\n                <>\n                    <div className=\"mb1\">\n                        <hr />\n                    </div>\n                    <CheckoutRow\n                        title={c('Title').t`Amount due`}\n                        amount={amountDue}\n                        currency={currency}\n                        className=\"text-bold m0 text-2xl\"\n                    />\n                </>\n            )}\n            <div className=\"mt1 mb1\">{submit}</div>\n            {!isOptimistic && amount > 0 && gift ? gift : null}\n        </Checkout>\n    );\n};\n\nexport default SubscriptionCheckout;\n","import { c } from 'ttag';\n\nimport { PAYMENT_METHOD_TYPE, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { Currency, SubscriptionCheckResponse } from '@proton/shared/lib/interfaces';\n\nimport { Price, PrimaryButton } from '../../../components';\nimport StyledPayPalButton from '../StyledPayPalButton';\nimport { PayPalHook } from '../usePayPal';\nimport { SUBSCRIPTION_STEPS } from './constants';\n\ninterface Props {\n    className?: string;\n    currency: Currency;\n    step: SUBSCRIPTION_STEPS;\n    onClose?: () => void;\n    checkResult?: SubscriptionCheckResponse;\n    loading?: boolean;\n    method?: PAYMENT_METHOD_TYPE;\n    paypal: PayPalHook;\n    disabled?: boolean;\n}\n\nconst SubscriptionSubmitButton = ({\n    className,\n    paypal,\n    currency,\n    step,\n    loading,\n    method,\n    checkResult,\n    disabled,\n    onClose,\n}: Props) => {\n    const amountDue = checkResult?.AmountDue || 0;\n\n    if (step === SUBSCRIPTION_STEPS.CUSTOMIZATION) {\n        return (\n            <PrimaryButton className={className} disabled={disabled} loading={loading} type=\"submit\">\n                {c('Action').t`Continue`}\n            </PrimaryButton>\n        );\n    }\n\n    if (amountDue === 0) {\n        return (\n            <PrimaryButton className={className} loading={loading} disabled={disabled} type=\"submit\">\n                {c('Action').t`Confirm`}\n            </PrimaryButton>\n        );\n    }\n\n    if (method === PAYMENT_METHOD_TYPES.PAYPAL) {\n        return <StyledPayPalButton flow=\"subscription\" paypal={paypal} className={className} amount={amountDue} />;\n    }\n\n    if (!loading && method && [PAYMENT_METHOD_TYPES.CASH, PAYMENT_METHOD_TYPES.BITCOIN].includes(method as any)) {\n        return (\n            <PrimaryButton className={className} disabled={disabled} loading={loading} onClick={onClose}>\n                {c('Action').t`Done`}\n            </PrimaryButton>\n        );\n    }\n\n    const price = (\n        <Price key=\"price\" currency={currency}>\n            {amountDue}\n        </Price>\n    );\n\n    return (\n        <PrimaryButton className={className} loading={loading} disabled={disabled} type=\"submit\">\n            {amountDue > 0 ? c('Action').jt`Pay ${price} now` : c('Action').t`Confirm`}\n        </PrimaryButton>\n    );\n};\n\nexport default SubscriptionSubmitButton;\n","import { c } from 'ttag';\n\nimport { CircleLoader } from '@proton/atoms/CircleLoader';\nimport { APPS, PAYMENT_METHOD_TYPE, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport appStoreSvg from '@proton/styles/assets/img/illustrations/app-store.svg';\nimport playStoreSvg from '@proton/styles/assets/img/illustrations/play-store.svg';\nimport mailThanksSvg from '@proton/styles/assets/img/illustrations/thank-you-mail.svg';\nimport vpnThanksSvg from '@proton/styles/assets/img/illustrations/thank-you-vpn.svg';\n\nimport { Href, PrimaryButton } from '../../../components';\nimport { useConfig } from '../../../hooks';\n\ninterface Props {\n    onClose?: () => void;\n    method?: PAYMENT_METHOD_TYPE;\n    loading?: boolean;\n}\n\nconst SubscriptionThanks = ({ method, onClose, loading }: Props) => {\n    const { APP_NAME } = useConfig();\n    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;\n\n    return (\n        <div className=\"relative\">\n            {loading && (\n                <div className=\"text-center absolute absolute-center pb4\">\n                    <CircleLoader size=\"large\" className=\"color-primary\" />\n                </div>\n            )}\n            <div className={loading ? 'visibility-hidden' : undefined}>\n                <h1 className=\"text-center mb0\">\n                    <img src={isVPN ? vpnThanksSvg : mailThanksSvg} alt=\"Thanks\" />\n                </h1>\n                {method && [PAYMENT_METHOD_TYPES.CASH, PAYMENT_METHOD_TYPES.BITCOIN].includes(method as any) ? (\n                    <p className=\"text-center mb1\">{c('Info')\n                        .t`Your account will be updated once the payment is cleared.`}</p>\n                ) : (\n                    <p className=\"text-center mb1 text-bold text-xl\">{c('Info').t`Account successfully updated`}</p>\n                )}\n                <p className=\"text-center mb2\">{c('Info')\n                    .t`Download your favorite app today and take privacy with you everywhere you go.`}</p>\n                <div className=\"mt1 mb2 text-center\">\n                    <Href\n                        url={\n                            isVPN\n                                ? 'https://play.google.com/store/apps/details?id=ch.protonvpn.android'\n                                : 'https://play.google.com/store/apps/details?id=ch.protonmail.android'\n                        }\n                        className=\"mr2\"\n                    >\n                        <img width=\"150\" src={playStoreSvg} alt=\"Play Store\" />\n                    </Href>\n                    <Href\n                        url={\n                            isVPN\n                                ? 'https://itunes.apple.com/us/app/protonvpn-fast-secure-vpn/id1437005085'\n                                : 'https://apps.apple.com/app/protonmail-encrypted-email/id979659905'\n                        }\n                    >\n                        <img width=\"150\" src={appStoreSvg} alt=\"App Store\" />\n                    </Href>\n                </div>\n                <div className=\"text-center pb2\">\n                    <PrimaryButton fullWidth onClick={onClose}>{c('Action').t`Close`}</PrimaryButton>\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default SubscriptionThanks;\n","import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { checkSubscription, deleteSubscription, subscribe } from '@proton/shared/lib/api/payments';\nimport { getShouldCalendarPreventSubscripitionChange, willHavePaidMail } from '@proton/shared/lib/calendar/plans';\nimport { APP_NAMES, DEFAULT_CURRENCY, DEFAULT_CYCLE, PLANS, PLAN_TYPES } from '@proton/shared/lib/constants';\nimport { API_CUSTOM_ERROR_CODES } from '@proton/shared/lib/errors';\nimport { getCheckout, getIsCustomCycle, getOptimisticCheckResult } from '@proton/shared/lib/helpers/checkout';\nimport { toMap } from '@proton/shared/lib/helpers/object';\nimport { hasBonuses } from '@proton/shared/lib/helpers/organization';\nimport { hasPlanIDs, supportAddons } from '@proton/shared/lib/helpers/planIDs';\nimport { getPlanIDs, hasMigrationDiscount, hasNewVisionary } from '@proton/shared/lib/helpers/subscription';\nimport {\n    Audience,\n    Currency,\n    Cycle,\n    PlanIDs,\n    PlansMap,\n    SubscriptionCheckResponse,\n    SubscriptionModel,\n} from '@proton/shared/lib/interfaces';\nimport { getFreeCheckResult } from '@proton/shared/lib/subscription/freePlans';\nimport { hasPaidMail } from '@proton/shared/lib/user/helpers';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport {\n    Icon,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    Tooltip,\n} from '../../../components';\nimport { classnames } from '../../../helpers';\nimport {\n    useApi,\n    useEventManager,\n    useGetCalendars,\n    useLoading,\n    useModals,\n    useNotifications,\n    useOrganization,\n    usePlans,\n    useSubscription,\n    useUser,\n    useVPNCountriesCount,\n    useVPNServersCount,\n} from '../../../hooks';\nimport GenericError from '../../error/GenericError';\nimport LossLoyaltyModal from '../LossLoyaltyModal';\nimport MemberDowngradeModal from '../MemberDowngradeModal';\nimport Payment from '../Payment';\nimport PaymentGiftCode from '../PaymentGiftCode';\nimport { handlePaymentToken } from '../paymentTokenHelper';\nimport usePayment from '../usePayment';\nimport CalendarDowngradeModal from './CalendarDowngradeModal';\nimport PlanCustomization from './PlanCustomization';\nimport { DiscountWarningModal, NewVisionaryWarningModal } from './PlanLossWarningModal';\nimport PlanSelection from './PlanSelection';\nimport SubscriptionCheckout from './SubscriptionCheckout';\nimport SubscriptionCycleSelector from './SubscriptionCycleSelector';\nimport SubscriptionSubmitButton from './SubscriptionSubmitButton';\nimport SubscriptionThanks from './SubscriptionThanks';\nimport { SUBSCRIPTION_STEPS, subscriptionModalClassName } from './constants';\nimport { getDefaultSelectedProductPlans } from './helpers';\n\nimport './SubscriptionModal.scss';\n\ninterface Props extends Pick<ModalProps<'div'>, 'open' | 'onClose' | 'onExit'> {\n    app: APP_NAMES;\n    step?: SUBSCRIPTION_STEPS;\n    cycle?: Cycle;\n    currency?: Currency;\n    planIDs?: PlanIDs;\n    coupon?: string | null;\n    disablePlanSelection?: boolean;\n    disableThanksStep?: boolean;\n    defaultAudience?: Audience;\n    disableCycleSelector?: boolean;\n    defaultSelectedProductPlans: ReturnType<typeof getDefaultSelectedProductPlans>;\n    onSuccess?: () => void;\n}\n\nexport interface Model {\n    step: SUBSCRIPTION_STEPS;\n    planIDs: PlanIDs;\n    currency: Currency;\n    cycle: Cycle;\n    coupon?: string | null;\n    gift?: string;\n}\n\nconst BACK: Partial<{ [key in SUBSCRIPTION_STEPS]: SUBSCRIPTION_STEPS }> = {\n    [SUBSCRIPTION_STEPS.CUSTOMIZATION]: SUBSCRIPTION_STEPS.PLAN_SELECTION,\n    [SUBSCRIPTION_STEPS.CHECKOUT]: SUBSCRIPTION_STEPS.CUSTOMIZATION,\n};\n\nconst getCodes = ({ gift, coupon }: Model) => [gift, coupon].filter(isTruthy);\n\nexport const useProration = (\n    model: Model,\n    subscription: SubscriptionModel,\n    plansMap: PlansMap,\n    checkResult?: SubscriptionCheckResponse\n) => {\n    const showProration = useMemo(() => {\n        const checkout = getCheckout({\n            planIDs: getPlanIDs(subscription),\n            plansMap,\n            checkResult,\n        });\n        const activePlan = checkout.planName as string;\n\n        const selectedPlans = Object.keys(model.planIDs);\n\n        const userBuysTheSamePlan = selectedPlans.includes(activePlan);\n\n        if (!checkResult || !userBuysTheSamePlan || checkResult.Proration === undefined) {\n            return true;\n        }\n\n        return checkResult.Proration !== 0;\n    }, [subscription, model, checkResult]);\n\n    return {\n        showProration,\n    };\n};\n\nconst SubscriptionModal = ({\n    app,\n    step = SUBSCRIPTION_STEPS.PLAN_SELECTION,\n    cycle = DEFAULT_CYCLE,\n    currency = DEFAULT_CURRENCY,\n    coupon,\n    planIDs = {},\n    onClose,\n    onSuccess,\n    disablePlanSelection,\n    disableCycleSelector: maybeDisableCycleSelector,\n    disableThanksStep,\n    defaultAudience = Audience.B2C,\n    defaultSelectedProductPlans,\n    ...rest\n}: Props) => {\n    const TITLE = {\n        [SUBSCRIPTION_STEPS.NETWORK_ERROR]: c('Title').t`Network error`,\n        [SUBSCRIPTION_STEPS.PLAN_SELECTION]: c('Title').t`Select a plan`,\n        [SUBSCRIPTION_STEPS.CUSTOMIZATION]: c('Title').t`Customize your plan`,\n        [SUBSCRIPTION_STEPS.CHECKOUT]: c('new_plans: title').t`Review subscription and pay`,\n        [SUBSCRIPTION_STEPS.UPGRADE]: '',\n        [SUBSCRIPTION_STEPS.THANKS]: '',\n    };\n\n    const topRef = useRef<HTMLDivElement>(null);\n    const api = useApi();\n    const [user] = useUser();\n    const [subscription] = useSubscription();\n    const { call } = useEventManager();\n    const { createModal } = useModals();\n    const { createNotification } = useNotifications();\n    const [plans = []] = usePlans();\n    const plansMap = toMap(plans, 'Name') as PlansMap;\n    const [vpnServers] = useVPNServersCount();\n    const [vpnCountries] = useVPNCountriesCount();\n    const [organization] = useOrganization();\n    const getCalendars = useGetCalendars();\n\n    const [loading, withLoading] = useLoading();\n    const [loadingCheck, withLoadingCheck] = useLoading();\n    const [loadingGift, withLoadingGift] = useLoading();\n    const [checkResult, setCheckResult] = useState<SubscriptionCheckResponse>();\n    const [audience, setAudience] = useState(defaultAudience);\n    const [selectedProductPlans, setSelectedProductPlans] = useState(defaultSelectedProductPlans);\n    const [model, setModel] = useState<Model>({\n        step,\n        cycle,\n        currency,\n        coupon,\n        planIDs,\n    });\n\n    const { showProration } = useProration(model, subscription, plansMap, checkResult);\n\n    const amountDue = checkResult?.AmountDue || 0;\n    const couponCode = checkResult?.Coupon?.Code;\n    const couponDescription = checkResult?.Coupon?.Description;\n    const creditsRemaining = (user.Credit + (checkResult?.Credit ?? 0)) / 100;\n\n    const subscriptionCouponCode = subscription?.CouponCode;\n    const latestValidCouponCodeRef = useRef('');\n\n    const handleUnsubscribe = async () => {\n        // Start promise early\n        const shouldCalendarPreventDowngradePromise = getShouldCalendarPreventSubscripitionChange({\n            hasPaidMail: hasPaidMail(user),\n            willHavePaidMail: false,\n            api,\n            getCalendars,\n        });\n\n        if (hasMigrationDiscount(subscription)) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<DiscountWarningModal type=\"downgrade\" onClose={reject} onConfirm={resolve} />);\n            });\n        }\n\n        if (await shouldCalendarPreventDowngradePromise) {\n            await new Promise<void>((resolve, reject) => {\n                const handleClose = () => {\n                    onClose?.();\n                    reject();\n                };\n                createModal(<CalendarDowngradeModal isDowngrade onConfirm={resolve} onClose={handleClose} />);\n            });\n        }\n\n        if (hasBonuses(organization)) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<LossLoyaltyModal organization={organization} onConfirm={resolve} onClose={reject} />);\n            });\n        }\n\n        if (organization.UsedMembers > 1) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<MemberDowngradeModal organization={organization} onConfirm={resolve} onClose={reject} />);\n            });\n        }\n\n        await api(deleteSubscription());\n        await call();\n        onSuccess?.();\n        onClose?.();\n        createNotification({ text: c('Success').t`You have successfully unsubscribed` });\n    };\n\n    const handlePlanWarnings = async (planIDs: PlanIDs) => {\n        const newPlanName = Object.keys(planIDs).find((planName) =>\n            plans.find((plan) => plan.Type === PLAN_TYPES.PLAN && plan.Name === planName)\n        );\n        if (hasNewVisionary(subscription) && PLANS.NEW_VISIONARY !== newPlanName) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(\n                    <NewVisionaryWarningModal\n                        type={!newPlanName ? 'downgrade' : 'switch'}\n                        onClose={reject}\n                        onConfirm={resolve}\n                    />\n                );\n            });\n        }\n    };\n\n    const handleSubscribe = async (params = {}) => {\n        try {\n            await handlePlanWarnings(model.planIDs);\n        } catch (e) {\n            return;\n        }\n\n        if (!hasPlanIDs(model.planIDs)) {\n            return handleUnsubscribe();\n        }\n\n        const shouldCalendarPreventSubscriptionChangePromise = getShouldCalendarPreventSubscripitionChange({\n            hasPaidMail: hasPaidMail(user),\n            willHavePaidMail: willHavePaidMail(model.planIDs, plans),\n            api,\n            getCalendars,\n        });\n\n        if (await shouldCalendarPreventSubscriptionChangePromise) {\n            return new Promise<void>((resolve, reject) => {\n                const handleClose = () => {\n                    onClose?.();\n                    reject();\n                };\n                createModal(<CalendarDowngradeModal onConfirm={resolve} onClose={handleClose} />);\n            });\n        }\n\n        try {\n            setModel({ ...model, step: SUBSCRIPTION_STEPS.UPGRADE });\n            await api({\n                ...subscribe(\n                    {\n                        Plans: model.planIDs,\n                        Codes: getCodes(model),\n                        Cycle: model.cycle,\n                        ...params, // Contains Payment, Amount and Currency\n                    },\n                    app\n                ),\n                timeout: 60000 * 2, // 2 minutes\n            });\n            await call();\n            if (disableThanksStep) {\n                onSuccess?.();\n                onClose?.();\n            } else {\n                setModel({ ...model, step: SUBSCRIPTION_STEPS.THANKS });\n            }\n        } catch (error: any) {\n            const { Code = 0 } = error.data || {};\n\n            if (Code === API_CUSTOM_ERROR_CODES.PAYMENTS_SUBSCRIPTION_AMOUNT_MISMATCH) {\n                await check(); // eslint-disable-line @typescript-eslint/no-use-before-define\n                // translator: this message pops in a notification, in case user is waiting really too long, or does the checkout in another tab, which makes this ones not valid/expiring\n                createNotification({ text: c('Error').t`Checkout expired, please try again`, type: 'error' });\n            }\n            setModel({ ...model, step: SUBSCRIPTION_STEPS.CHECKOUT });\n            throw error;\n        }\n    };\n\n    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =\n        usePayment({\n            amount: model.step === SUBSCRIPTION_STEPS.CHECKOUT ? amountDue : 0, // Define amount only in the payment step to generate payment tokens\n            currency: checkResult?.Currency || DEFAULT_CURRENCY,\n            onPay(params) {\n                return withLoading(handleSubscribe(params));\n            },\n        });\n    const creditCardTopRef = useRef<HTMLDivElement>(null);\n\n    const check = async (newModel: Model = model, wantToApplyNewGiftCode: boolean = false): Promise<void> => {\n        const copyNewModel = { ...newModel };\n\n        if (copyNewModel.step === SUBSCRIPTION_STEPS.CUSTOMIZATION && !supportAddons(copyNewModel.planIDs)) {\n            copyNewModel.step = SUBSCRIPTION_STEPS.CHECKOUT;\n        }\n\n        if (!hasPlanIDs(newModel.planIDs)) {\n            setCheckResult(getFreeCheckResult(model.currency, model.cycle));\n            setModel(copyNewModel);\n            return;\n        }\n\n        try {\n            const result = await api<SubscriptionCheckResponse>(\n                checkSubscription({\n                    Plans: newModel.planIDs,\n                    Currency: newModel.currency,\n                    Cycle: newModel.cycle,\n                    Codes: getCodes(newModel),\n                })\n            );\n\n            const { Gift = 0 } = result;\n            const { Code = '' } = result.Coupon || {}; // Coupon can equal null\n\n            if (wantToApplyNewGiftCode && newModel.gift?.toLowerCase() !== Code.toLowerCase() && !Gift) {\n                createNotification({ text: c('Error').t`Invalid code`, type: 'error' });\n            }\n\n            if (Code) {\n                latestValidCouponCodeRef.current = Code;\n            }\n            copyNewModel.coupon = Code || subscriptionCouponCode || latestValidCouponCodeRef.current;\n\n            if (!Gift) {\n                delete copyNewModel.gift;\n            }\n\n            setCheckResult(result);\n            setModel(copyNewModel);\n        } catch (error: any) {\n            if (error.name === 'OfflineError') {\n                setModel({ ...model, step: SUBSCRIPTION_STEPS.NETWORK_ERROR });\n            }\n        }\n    };\n\n    const handleCheckout = async () => {\n        const params = await handlePaymentToken({\n            params: {\n                Amount: amountDue,\n                Currency: model.currency,\n                ...parameters,\n            },\n            createModal,\n            api,\n        });\n\n        return handleSubscribe(params);\n    };\n\n    const handleGift = (gift = '') => {\n        if (loadingCheck) {\n            return;\n        }\n        if (!gift) {\n            const withoutGift = { ...model };\n            delete withoutGift.gift;\n            return withLoadingGift(check(withoutGift));\n        }\n        void withLoadingGift(check({ ...model, gift }, true));\n    };\n\n    const handleChangeCurrency = (currency: Currency) => {\n        if (loadingCheck || currency === model.currency) {\n            return;\n        }\n        withLoadingCheck(check({ ...model, currency }));\n    };\n\n    const handleChangeCycle = (cycle: Cycle) => {\n        if (loadingCheck || cycle === model.cycle) {\n            return;\n        }\n        withLoadingCheck(check({ ...model, cycle }));\n    };\n\n    useEffect(() => {\n        // Trigger once to initialise the check values\n        void withLoadingCheck(check());\n    }, []);\n\n    const backStep =\n        model.step === SUBSCRIPTION_STEPS.CHECKOUT && !supportAddons(model.planIDs)\n            ? SUBSCRIPTION_STEPS.PLAN_SELECTION\n            : BACK[model.step];\n    const isFreePlanSelected = !hasPlanIDs(model.planIDs);\n    const isFreeUserWithFreePlanSelected = user.isFree && isFreePlanSelected;\n\n    const disableCycleSelector = isFreePlanSelected || maybeDisableCycleSelector || getIsCustomCycle(model.cycle);\n\n    useEffect(() => {\n        // Each time the user switch between steps, it takes the user to the top of the modal\n        topRef.current?.scrollIntoView();\n    }, [model.step]);\n\n    return (\n        <ModalTwo\n            className={classnames([\n                subscriptionModalClassName,\n                [\n                    SUBSCRIPTION_STEPS.PLAN_SELECTION,\n                    SUBSCRIPTION_STEPS.CUSTOMIZATION,\n                    SUBSCRIPTION_STEPS.CHECKOUT,\n                ].includes(model.step) && 'subscription-modal--fixed-height',\n                [SUBSCRIPTION_STEPS.PLAN_SELECTION].includes(model.step) && 'subscription-modal--large-width',\n                [SUBSCRIPTION_STEPS.CUSTOMIZATION, SUBSCRIPTION_STEPS.CHECKOUT].includes(model.step) &&\n                    'subscription-modal--medium-width',\n            ])}\n            onSubmit={(e: FormEvent) => {\n                e.preventDefault();\n                if (loadingCheck || loadingGift) {\n                    return;\n                }\n                if (!handleCardSubmit()) {\n                    creditCardTopRef.current?.scrollIntoView();\n                    return;\n                }\n                withLoading(handleCheckout());\n            }}\n            onClose={onClose}\n            {...rest}\n            as=\"form\"\n            size=\"large\"\n        >\n            <ModalTwoHeader title={TITLE[model.step]} />\n            <ModalTwoContent>\n                <div ref={topRef} />\n                {model.step === SUBSCRIPTION_STEPS.NETWORK_ERROR && <GenericError />}\n                {model.step === SUBSCRIPTION_STEPS.PLAN_SELECTION && (\n                    <PlanSelection\n                        loading={loadingCheck}\n                        plans={plans}\n                        plansMap={plansMap}\n                        vpnServers={vpnServers}\n                        vpnCountries={vpnCountries}\n                        currency={model.currency}\n                        cycle={model.cycle}\n                        planIDs={model.planIDs}\n                        mode=\"modal\"\n                        subscription={subscription}\n                        onChangePlanIDs={(planIDs) =>\n                            withLoadingCheck(check({ ...model, planIDs, step: SUBSCRIPTION_STEPS.CUSTOMIZATION }))\n                        }\n                        onChangeCycle={handleChangeCycle}\n                        onChangeCurrency={handleChangeCurrency}\n                        onChangeAudience={setAudience}\n                        audience={audience}\n                        selectedProductPlans={selectedProductPlans}\n                        onChangeSelectedProductPlans={setSelectedProductPlans}\n                        organization={organization}\n                    />\n                )}\n                {model.step === SUBSCRIPTION_STEPS.CUSTOMIZATION && (\n                    <div className=\"subscriptionCheckout-top-container\">\n                        <div className=\"flex-item-fluid on-mobile-w100 pr2 on-tablet-landscape-pr1 on-mobile-pr0 pt2\">\n                            <div className=\"max-w50e\">\n                                <PlanCustomization\n                                    loading={loadingCheck}\n                                    currency={model.currency}\n                                    cycle={model.cycle}\n                                    plansMap={plansMap}\n                                    planIDs={model.planIDs}\n                                    organization={organization}\n                                    onChangePlanIDs={(planIDs) => setModel({ ...model, planIDs })}\n                                />\n                            </div>\n                        </div>\n                        <div className=\"subscriptionCheckout-column bg-weak on-mobile-w100 rounded\">\n                            <div className=\"subscriptionCheckout-container sticky-top\">\n                                <SubscriptionCheckout\n                                    submit={\n                                        <Button\n                                            color=\"norm\"\n                                            loading={loading}\n                                            onClick={() => {\n                                                const run = async () => {\n                                                    await check();\n                                                    return setModel((old) => ({\n                                                        ...old,\n                                                        step: SUBSCRIPTION_STEPS.CHECKOUT,\n                                                    }));\n                                                };\n                                                withLoading(run());\n                                            }}\n                                            fullWidth\n                                        >\n                                            {c('new_plans: action').t`Continue to review`}\n                                        </Button>\n                                    }\n                                    checkResult={getOptimisticCheckResult({\n                                        cycle: model.cycle,\n                                        planIDs: model.planIDs,\n                                        plansMap,\n                                    })}\n                                    plansMap={plansMap}\n                                    vpnServers={vpnServers}\n                                    isOptimistic={true}\n                                    loading={loadingCheck}\n                                    currency={model.currency}\n                                    cycle={model.cycle}\n                                    planIDs={model.planIDs}\n                                    onChangeCurrency={handleChangeCurrency}\n                                />\n                            </div>\n                        </div>\n                    </div>\n                )}\n                {model.step === SUBSCRIPTION_STEPS.CHECKOUT && (\n                    <div className=\"subscriptionCheckout-top-container\">\n                        <div className=\"flex-item-fluid on-mobile-w100 pr2 on-tablet-landscape-pr1 on-mobile-pr0 pt2\">\n                            <div className=\"mlauto mrauto max-w37e subscriptionCheckout-options \">\n                                {!disableCycleSelector && (\n                                    <>\n                                        <h2 className=\"text-2xl text-bold mb1\">{c('Label').t`Subscription options`}</h2>\n                                        <div className=\"mb2\">\n                                            <SubscriptionCycleSelector\n                                                mode=\"buttons\"\n                                                plansMap={plansMap}\n                                                planIDs={model.planIDs}\n                                                cycle={model.cycle}\n                                                currency={model.currency}\n                                                onChangeCycle={handleChangeCycle}\n                                                disabled={loadingCheck}\n                                            />\n                                        </div>\n                                    </>\n                                )}\n                                {/* avoid mounting/unmounting the component which re-triggers the hook */}\n                                <div className={amountDue ? undefined : 'hidden'}>\n                                    <Payment\n                                        type=\"subscription\"\n                                        paypal={paypal}\n                                        paypalCredit={paypalCredit}\n                                        method={method}\n                                        amount={amountDue}\n                                        currency={checkResult?.Currency}\n                                        coupon={couponCode}\n                                        card={card}\n                                        onMethod={setMethod}\n                                        onCard={setCard}\n                                        cardErrors={cardErrors}\n                                        creditCardTopRef={creditCardTopRef}\n                                    />\n                                </div>\n                                <div className={amountDue || !checkResult ? 'hidden' : undefined}>\n                                    <h2 className=\"text-2xl text-bold mb1\">{c('Label').t`Payment details`}</h2>\n                                    <div className=\"mb1\">{c('Info').t`No payment is required at this time.`}</div>\n                                    {checkResult?.Credit && creditsRemaining ? (\n                                        <div className=\"mb1\">{c('Info')\n                                            .t`Please note that upon clicking the Confirm button, your account will have ${creditsRemaining} credits remaining.`}</div>\n                                    ) : null}\n                                </div>\n                            </div>\n                        </div>\n                        <div className=\"subscriptionCheckout-column bg-weak on-mobile-w100 rounded\">\n                            <div className=\"subscriptionCheckout-container sticky-top\">\n                                <SubscriptionCheckout\n                                    submit={\n                                        <SubscriptionSubmitButton\n                                            currency={model.currency}\n                                            onClose={onClose}\n                                            paypal={paypal}\n                                            step={model.step}\n                                            loading={loading}\n                                            method={method}\n                                            checkResult={checkResult}\n                                            className=\"w100\"\n                                            disabled={isFreeUserWithFreePlanSelected || !canPay}\n                                        />\n                                    }\n                                    plansMap={plansMap}\n                                    checkResult={checkResult}\n                                    vpnServers={vpnServers}\n                                    loading={loadingCheck}\n                                    currency={model.currency}\n                                    cycle={model.cycle}\n                                    planIDs={model.planIDs}\n                                    gift={\n                                        <>\n                                            {couponCode && (\n                                                <div className=\"flex flex-align-items-center mb0-25\">\n                                                    <Icon name=\"gift\" className=\"mr0-5 mb0-25\" />\n                                                    <Tooltip title={couponDescription}>\n                                                        <code>{couponCode.toUpperCase()}</code>\n                                                    </Tooltip>\n                                                </div>\n                                            )}\n                                            <PaymentGiftCode\n                                                key={\n                                                    /* Reset the toggle state when a coupon code gets applied */\n                                                    couponCode\n                                                }\n                                                giftCode={model.gift}\n                                                onApply={handleGift}\n                                                loading={loadingGift}\n                                            />\n                                        </>\n                                    }\n                                    onChangeCurrency={handleChangeCurrency}\n                                    showProration={showProration}\n                                    nextSubscriptionStart={subscription.PeriodEnd}\n                                />\n                            </div>\n                        </div>\n                    </div>\n                )}\n                {model.step === SUBSCRIPTION_STEPS.UPGRADE && <SubscriptionThanks loading={true} method={method} />}\n                {model.step === SUBSCRIPTION_STEPS.THANKS && (\n                    <SubscriptionThanks\n                        method={method}\n                        onClose={() => {\n                            onSuccess?.();\n                            onClose?.();\n                        }}\n                    />\n                )}\n            </ModalTwoContent>\n            {(disablePlanSelection && backStep === SUBSCRIPTION_STEPS.PLAN_SELECTION) ||\n            backStep === undefined ? null : (\n                <ModalTwoFooter>\n                    <Button\n                        onClick={() => {\n                            setModel({ ...model, step: backStep });\n                        }}\n                    >{c('Action').t`Back`}</Button>\n                </ModalTwoFooter>\n            )}\n        </ModalTwo>\n    );\n};\n\nexport default SubscriptionModal;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { AlertModal, AlertModalProps, Href } from '../../../components';\n\nconst SubscriptionModalDisabled = (props: Omit<AlertModalProps, 'title' | 'buttons' | 'children'>) => {\n    const learnMore = <Href url={getKnowledgeBaseUrl('/upgrading-to-new-proton-plan')}>{c('Link').t`Learn more`}</Href>;\n    return (\n        <AlertModal\n            {...props}\n            title={c('new_plans: title').t`Improved plans coming soon!`}\n            buttons={<Button color=\"norm\" onClick={props.onClose}>{c('new_plans: action').t`Got it`}</Button>}\n        >\n            <div className=\"text-pre-wrap\">\n                {c('Info')\n                    .t`We’re upgrading your current plan to an improved plan that offers more for the same price. While our systems are updating, you won’t be able to change it. We’ll email you as soon as it’s done.`}{' '}\n                {learnMore}\n            </div>\n        </AlertModal>\n    );\n};\n\nexport default SubscriptionModalDisabled;\n","import { ReactNode, createContext, useContext, useRef } from 'react';\n\nimport { APP_NAMES, PLANS } from '@proton/shared/lib/constants';\nimport { toMap } from '@proton/shared/lib/helpers/object';\nimport { switchPlan } from '@proton/shared/lib/helpers/planIDs';\nimport {\n    getHasB2BPlan,\n    getHasLegacyPlans,\n    getIsB2BPlan,\n    getNormalCycleFromCustomCycle,\n    getPlanIDs,\n} from '@proton/shared/lib/helpers/subscription';\nimport { Audience, Currency, Cycle, PlanIDs } from '@proton/shared/lib/interfaces';\nimport noop from '@proton/utils/noop';\n\nimport { useModalState } from '../../../components';\nimport { useOrganization, usePlans, useSubscription, useUser } from '../../../hooks';\nimport SubscriptionModal from './SubscriptionModal';\nimport SubscriptionModalDisabled from './SubscriptionModalDisabled';\nimport { SUBSCRIPTION_STEPS } from './constants';\nimport { SelectedProductPlans, getCurrency, getDefaultSelectedProductPlans } from './helpers';\n\ninterface OpenCallbackProps {\n    step: SUBSCRIPTION_STEPS;\n    defaultAudience?: Audience;\n    defaultSelectedProductPlans?: SelectedProductPlans;\n    plan?: PLANS;\n    planIDs?: PlanIDs;\n    cycle?: Cycle;\n    currency?: Currency;\n    coupon?: string;\n    disablePlanSelection?: boolean;\n    disableCycleSelector?: boolean;\n    disableThanksStep?: boolean;\n    onClose?: () => void;\n    onSuccess?: () => void;\n    fullscreen?: boolean;\n}\n\nexport type OpenSubscriptionModalCallback = (props: OpenCallbackProps) => void;\n\ntype ContextProps = [OpenSubscriptionModalCallback, boolean];\n\nconst SubscriptionModalContext = createContext<ContextProps>([noop, false]);\n\nexport const useSubscriptionModal = () => {\n    return useContext(SubscriptionModalContext);\n};\n\ninterface Props {\n    children: ReactNode;\n    app: APP_NAMES;\n    onClose?: () => void;\n}\n\nconst SubscriptionModalProvider = ({ children, app, onClose }: Props) => {\n    const [subscription, loadingSubscription] = useSubscription();\n    const [organization, loadingOrganization] = useOrganization();\n    const [user] = useUser();\n    const [plans = [], loadingPlans] = usePlans();\n    const subscriptionProps = useRef<{\n        planIDs: PlanIDs;\n        defaultAudience?: Audience;\n        defaultSelectedProductPlans: SelectedProductPlans;\n        step: SUBSCRIPTION_STEPS;\n        currency?: Currency;\n        cycle?: Cycle;\n        coupon?: string;\n        disablePlanSelection?: boolean;\n        disableCycleSelector?: boolean;\n        disableThanksStep?: boolean;\n        onClose?: () => void;\n        onSuccess?: () => void;\n        fullscreen?: boolean;\n    } | null>(null);\n    const [modalState, setModalState, render] = useModalState();\n\n    const loading = Boolean(loadingSubscription || loadingPlans || loadingOrganization);\n\n    const plansMap = toMap(plans, 'Name');\n    const subscriptionPlanIDs = getPlanIDs(subscription);\n\n    return (\n        <>\n            {render &&\n                subscriptionProps.current &&\n                (getHasLegacyPlans(subscription) ? (\n                    <SubscriptionModalDisabled {...modalState} />\n                ) : (\n                    <SubscriptionModal\n                        app={app}\n                        {...subscriptionProps.current}\n                        {...modalState}\n                        onClose={() => {\n                            onClose?.();\n                            subscriptionProps?.current?.onClose?.();\n                            modalState.onClose();\n                        }}\n                    />\n                ))}\n            <SubscriptionModalContext.Provider\n                value={[\n                    ({\n                        planIDs: maybePlanIDs,\n                        plan,\n                        step,\n                        currency,\n                        cycle,\n                        coupon,\n                        defaultAudience,\n                        defaultSelectedProductPlans,\n                        disablePlanSelection,\n                        disableCycleSelector,\n                        disableThanksStep,\n                        onClose,\n                        onSuccess,\n                        fullscreen,\n                    }) => {\n                        if (loading || render) {\n                            return;\n                        }\n\n                        // The 15 and 30 month cycle are only valid coming from the black friday modal.\n                        // or Edit billing details.\n                        const subscriptionCycle = disablePlanSelection\n                            ? subscription.Cycle\n                            : getNormalCycleFromCustomCycle(subscription.Cycle);\n\n                        const planIDs = plan\n                            ? switchPlan({\n                                  planIDs: subscriptionPlanIDs,\n                                  planID: plansMap[plan].Name,\n                                  organization,\n                                  plans,\n                              })\n                            : maybePlanIDs || subscriptionPlanIDs;\n\n                        subscriptionProps.current = {\n                            planIDs,\n                            step,\n                            currency: currency || getCurrency(user, subscription, plans),\n                            cycle: cycle || subscriptionCycle,\n                            coupon: coupon || subscription.CouponCode || undefined,\n                            defaultAudience:\n                                defaultAudience || (plan && getIsB2BPlan(plan)) || getHasB2BPlan(subscription)\n                                    ? Audience.B2B\n                                    : Audience.B2C,\n                            defaultSelectedProductPlans:\n                                defaultSelectedProductPlans || getDefaultSelectedProductPlans(app, planIDs),\n                            disablePlanSelection,\n                            disableCycleSelector,\n                            disableThanksStep,\n                            onClose,\n                            onSuccess,\n                            fullscreen,\n                        };\n                        setModalState(true);\n                    },\n                    loading,\n                ]}\n            >\n                {children}\n            </SubscriptionModalContext.Provider>\n        </>\n    );\n};\n\nexport default SubscriptionModalProvider;\n","export enum SUBSCRIPTION_STEPS {\n    NETWORK_ERROR,\n    PLAN_SELECTION,\n    CUSTOMIZATION,\n    CHECKOUT,\n    UPGRADE,\n    THANKS,\n}\n\nexport const subscriptionModalClassName = 'subscription-modal';\n","import { getUnixTime } from 'date-fns';\n\nimport { APPS, APP_NAMES, CYCLE, DEFAULT_CURRENCY, PLANS, PLAN_SERVICES } from '@proton/shared/lib/constants';\nimport { hasBit } from '@proton/shared/lib/helpers/bitset';\nimport { hasVpnBasic, hasVpnPlus } from '@proton/shared/lib/helpers/subscription';\nimport {\n    Audience,\n    Cycle,\n    LatestSubscription,\n    Plan,\n    PlanIDs,\n    Subscription,\n    UserModel,\n} from '@proton/shared/lib/interfaces';\n\nconst OCTOBER_01 = getUnixTime(new Date(Date.UTC(2021, 9, 1)));\n\n/**\n * Calculate total for a specific subscription configuration\n */\nexport const getSubTotal = ({\n    plansMap,\n    cycle,\n    plans,\n    services,\n}: {\n    plansMap: { [key: string]: number };\n    cycle: Cycle;\n    plans: Plan[];\n    services?: PLAN_SERVICES;\n}) => {\n    return Object.entries(plansMap).reduce<number>((acc, [planName, quantity]) => {\n        if (!quantity) {\n            return acc;\n        }\n        const plan = plans.find(({ Name, Services }) => {\n            if (services) {\n                return Name === planName && hasBit(Services, services);\n            }\n            return Name === planName;\n        });\n        const amount = plan?.Pricing?.[cycle] || 0;\n        return acc + quantity * amount;\n    }, 0);\n};\n\n/**\n * Check if the current user is eligible to Black Friday discount\n */\nexport const getBlackFridayEligibility = (subscription: Subscription, latestSubscription?: LatestSubscription) => {\n    if (subscription?.Plans?.length === 1) {\n        // Eligible if you are on a vpn plus and monthly cycle\n        if (hasVpnPlus(subscription) && subscription.Plans[0]?.Cycle === CYCLE.MONTHLY) {\n            return true;\n        }\n\n        // Eligible if you are on a vpn basic\n        if (hasVpnBasic(subscription)) {\n            return true;\n        }\n    }\n\n    // Anyone else who had a paid plan at any point in time after Oct 2021 is not eligible\n    if ((latestSubscription?.LastSubscriptionEnd ?? 0) > OCTOBER_01) {\n        return false;\n    }\n\n    // Eligible if free plan\n    if (!subscription?.Plans?.length) {\n        return true;\n    }\n\n    return false;\n};\n\nexport const getCurrency = (\n    user: UserModel | undefined,\n    subscription: Subscription | undefined,\n    plans: Plan[] | undefined\n) => {\n    return user?.Currency || subscription?.Currency || plans?.[0]?.Currency || DEFAULT_CURRENCY;\n};\n\nexport const getDefaultSelectedProductPlans = (appName: APP_NAMES, planIDs: PlanIDs) => {\n    let defaultB2CPlan = PLANS.MAIL;\n    if (appName === APPS.PROTONVPN_SETTINGS) {\n        defaultB2CPlan = PLANS.VPN;\n    } else if (appName === APPS.PROTONDRIVE) {\n        defaultB2CPlan = PLANS.DRIVE;\n    }\n    const matchingB2CPlan = [PLANS.MAIL, PLANS.VPN, PLANS.DRIVE].find((x) => planIDs[x]);\n    const matchingB2BPlan = [PLANS.MAIL_PRO, PLANS.DRIVE_PRO].find((x) => planIDs[x]);\n    const defaultB2BPlan = PLANS.MAIL_PRO;\n    return {\n        [Audience.B2C]: matchingB2CPlan || defaultB2CPlan,\n        [Audience.B2B]: matchingB2BPlan || defaultB2BPlan,\n    };\n};\nexport type SelectedProductPlans = ReturnType<typeof getDefaultSelectedProductPlans>;\n","import { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\n\nimport {\n    Alert,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    ModalProps,\n} from '../../../components';\n\ninterface Props extends ModalProps {\n    onConfirm: () => void;\n    hasReset: boolean;\n    hasNotify: boolean;\n}\n\nconst ConfirmRemoveEmailModal = ({ hasReset, hasNotify, onConfirm, onClose, ...rest }: Props) => {\n    return (\n        <Modal onClose={onClose} {...rest}>\n            <ModalHeader title={c('Title').t`Confirm address`} />\n            <ModalContent>\n                <Alert type=\"warning\">\n                    {hasReset &&\n                        !hasNotify &&\n                        c('Warning').t`By deleting this address, you will no longer be able to recover your account.`}\n                    {hasNotify &&\n                        !hasReset &&\n                        c('Warning')\n                            .t`By deleting this address, you will no longer be able to receive daily email notifications.`}\n                    {hasNotify &&\n                        hasReset &&\n                        c('Warning')\n                            .t`By deleting this address, you will no longer be able to recover your account or receive daily email notifications.`}\n                    <br />\n                    <br />\n                    {c('Warning').t`Are you sure you want to delete the address?`}\n                </Alert>\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button\n                    color=\"norm\"\n                    onClick={() => {\n                        onConfirm();\n                        onClose?.();\n                    }}\n                >\n                    {c('Action').t`Confirm`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ConfirmRemoveEmailModal;\n","import { useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms';\nimport { postVerifySend } from '@proton/shared/lib/api/verify';\nimport { UserSettings } from '@proton/shared/lib/interfaces';\n\nimport { AlertModal, ModalProps } from '../../../components';\nimport { useApi, useNotifications } from '../../../hooks';\n\ninterface Props extends ModalProps {\n    email: UserSettings['Email'];\n}\n\nconst VerifyRecoveryEmailModal = ({ email, onClose, ...rest }: Props) => {\n    const [loading, setLoading] = useState(false);\n    const api = useApi();\n    const { createNotification } = useNotifications();\n\n    const handleSendVerificationEmailClick = async () => {\n        setLoading(true);\n        await api(postVerifySend({ Type: 'recovery_email' }));\n\n        createNotification({\n            type: 'success',\n            tex