 validator, onFormSubmit } = useFormErrors();\n    const [verifyRecoveryEmailModal, setVerifyRecoveryEmailModalOpen, renderVerifyRecoveryEmailModal] = useModalState();\n    const [authModal, setAuthModal, renderAuthModal] = useModalState();\n    const [confirmModal, setConfirmModal, renderConfirmModal] = useModalState();\n\n    const loading = renderVerifyRecoveryEmailModal || renderConfirmModal || renderAuthModal;\n    const confirmStep = !input && (hasReset || hasNotify);\n\n    return (\n        <>\n            {renderAuthModal && (\n                <AuthModal\n                    {...authModal}\n                    onCancel={undefined}\n                    onSuccess={async () => {\n                        await call();\n                        createNotification({ text: c('Success').t`Email updated` });\n                    }}\n                    config={updateEmail({ Email: input })}\n                />\n            )}\n            {renderConfirmModal && (\n                <ConfirmRemoveEmailModal\n                    hasReset={hasReset}\n                    hasNotify={hasNotify}\n                    {...confirmModal}\n                    onConfirm={() => {\n                        setAuthModal(true);\n                    }}\n                />\n            )}\n            {renderVerifyRecoveryEmailModal && <VerifyRecoveryEmailModal email={email} {...verifyRecoveryEmailModal} />}\n            <form\n                className={classnames(['flex flex-wrap on-mobile-flex-column', className])}\n                onSubmit={(e) => {\n                    e.preventDefault();\n                    if (!onFormSubmit()) {\n                        return;\n                    }\n                    if (confirmStep) {\n                        setConfirmModal(true);\n                    } else {\n                        setAuthModal(true);\n                    }\n                }}\n            >\n                <div className=\"mr1 mb1 on-mobile-mr0 flex-item-fluid min-w14e\" title={email.Value || ''}>\n                    <InputFieldTwo\n                        type=\"email\"\n                        autoComplete=\"email\"\n                        id=\"recovery-email-input\"\n                        disableChange={loading}\n                        value={input || ''}\n                        error={validator([input && emailValidator(input)].filter(isTruthy))}\n                        onValue={setInput}\n                        assistiveText={\n                            email.Value &&\n                            (email.Status === SETTINGS_STATUS.UNVERIFIED ? (\n                                <>\n                                    <Icon\n                                        className=\"color-danger flex-item-noshrink aligntop mr0-25\"\n                                        name=\"exclamation-circle-filled\"\n                                    />\n                                    <span className=\"color-norm mr0-5\">{c('Recovery Email')\n                                        .t`Email address not yet verified.`}</span>\n                                    <button\n                                        className=\"link\"\n                                        type=\"button\"\n                                        onClick={() => setVerifyRecoveryEmailModalOpen(true)}\n                                    >\n                                        {c('Recovery Email').t`Verify now`}\n                                    </button>\n                                </>\n                            ) : (\n                                <>\n                                    <Icon\n                                        className=\"color-success flex-item-noshrink aligntop mr0-25\"\n                                        name=\"checkmark-circle-filled\"\n                                    />\n                                    <span className=\"mr0-5\">{c('Recovery Email')\n                                        .t`Email address has been verified.`}</span>\n                                </>\n                            ))\n                        }\n                    />\n                </div>\n                <div className=\"mb0-5\">\n                    <Button\n                        type=\"submit\"\n                        shape=\"outline\"\n                        disabled={(email.Value || '') === input}\n                        loading={loading}\n                        data-testid=\"account:recovery:emailSubmit\"\n                    >\n                        {c('Action').t`Save`}\n                    </Button>\n                </div>\n            </form>\n        </>\n    );\n};\n\nexport default RecoveryEmail;\n","import { Cache } from '@proton/shared/lib/helpers/cache';\n\ntype CacheValue<V, D> =\n    | {\n          dependency: D;\n          promise: Promise<V>;\n      }\n    | {\n          dependency: D;\n          result: V;\n      };\n\n/**\n * Cache a promise by a key, and re-run it when the dependency changes.\n */\nexport const cachedPromise = <K, V, D>(\n    cache: Cache<K, CacheValue<V, D>>,\n    key: K,\n    miss: () => Promise<V>,\n    dependency: D\n) => {\n    const cachedValue = cache.get(key);\n    if (cachedValue) {\n        const { dependency: oldDependency } = cachedValue;\n\n        if (dependency === oldDependency) {\n            return 'promise' in cachedValue ? cachedValue.promise : Promise.resolve(cachedValue.result);\n        }\n    }\n\n    const promise = miss();\n\n    cache.set(key, {\n        dependency,\n        promise,\n    });\n\n    promise.then((result) => {\n        const cachedValue = cache.get(key);\n\n        if (!cachedValue) {\n            throw new Error(`Cached value for ${key} was overwritten unexpectedly`);\n        }\n\n        if ('promise' in cachedValue && promise !== cachedValue.promise) {\n            return result;\n        }\n\n        cache.set(key, {\n            dependency,\n            result,\n        });\n\n        return result;\n    });\n\n    return promise;\n};\n","import { useCallback, useEffect } from 'react';\n\nimport useApi from './useApi';\nimport useAsync from './useAsync';\n\nexport type QueryFunction = (...args: any[]) => { method: string; url: string };\n\ninterface Result<R, U extends any[]> {\n    result: R | undefined;\n    error: Error;\n    loading: boolean;\n    request: (...args: U) => Promise<R>;\n}\n\nconst useApiResult = <R, F extends QueryFunction = QueryFunction>(\n    fn: QueryFunction,\n    dependencies?: any[]\n): Result<R, Parameters<F>> => {\n    const request = useApi();\n    const { loading, result, error, run } = useAsync(true);\n\n    // Either user specified dependencies or empty array to always cancel requests on unmount.\n    const hookDependencies = dependencies || [];\n\n    // Callback updates\n    const requestAndSetResults = useCallback(\n        (...args: Parameters<F>) => {\n            const promise = request<R>(fn(...args));\n            run(promise);\n            return promise;\n        },\n        [request, run, fn]\n    );\n\n    useEffect(() => {\n        // If user has specified any dependencies, auto request\n        if (dependencies) {\n            requestAndSetResults(...([] as unknown as Parameters<F>)).catch(() => {\n                // catch the error to stop the \"uncaught exception error\"\n            });\n        }\n    }, [...hookDependencies]);\n\n    if (error) {\n        // Throw in render to allow the error boundary to catch it\n        throw error;\n    }\n\n    return {\n        result,\n        error,\n        loading,\n        request: requestAndSetResults,\n    };\n};\n\nexport default useApiResult;\n","import { useCallback } from 'react';\n\nimport useApi from './useApi';\nimport { QueryFunction } from './useApiResult';\nimport useAsync from './useAsync';\n\ninterface Result<R, U extends any[]> {\n    loading: boolean;\n    request: (...args: U) => Promise<R>;\n}\n\nconst useApiWithoutResult = <R, F extends QueryFunction = QueryFunction>(fn: F): Result<R, Parameters<F>> => {\n    const request = useApi();\n    const { loading, run } = useAsync(false);\n\n    const requestAndSetLoading = useCallback(\n        (...args) => {\n            const promise = request<R>(fn(...args));\n            run(promise);\n            return promise;\n        },\n        [request, run, fn]\n    );\n\n    return {\n        loading,\n        request: requestAndSetLoading,\n    };\n};\n\nexport default useApiWithoutResult;\n","import { useCallback, useReducer, useRef } from 'react';\n\nimport useIsMounted from '@proton/hooks/useIsMounted';\n\nconst DEFAULT_STATE = {\n    loading: false,\n};\n\nconst reducer = (state, action) => {\n    switch (action.type) {\n        case 'loading':\n            return {\n                ...state,\n                loading: true,\n            };\n        case 'success':\n            return {\n                error: undefined,\n                loading: false,\n                result: action.payload,\n            };\n        default:\n        case 'error':\n            return {\n                result: undefined,\n                loading: false,\n                error: action.payload,\n            };\n    }\n};\n\nconst useAsync = (setResults = true) => {\n    const [{ loading, result, error }, dispatch] = useReducer(reducer, DEFAULT_STATE);\n    const isMounted = useIsMounted();\n    const promiseRef = useRef();\n\n    const run = useCallback(async (promise) => {\n        const isCurrentPromise = () => promiseRef.current === promise;\n        promiseRef.current = promise;\n\n        dispatch({ type: 'loading' });\n        try {\n            const data = await promise;\n            if (isMounted() && isCurrentPromise()) {\n                dispatch({ type: 'success', payload: setResults ? data : undefined });\n            }\n            return data;\n        } catch (e) {\n            if (isMounted() && isCurrentPromise() && e.name !== 'AbortError') {\n                dispatch({ type: 'error', payload: setResults ? e : undefined });\n            }\n            throw e;\n        }\n    }, []);\n\n    return {\n        result,\n        error,\n        loading,\n        run,\n    };\n};\n\nexport default useAsync;\n","import { useCallback } from 'react';\n\nimport { CalendarUserSettings as tsCalendarUserSettings } from '@proton/shared/lib/interfaces/calendar';\nimport { CalendarUserSettingsModel } from '@proton/shared/lib/models/calendarSettingsModel';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetCalendarUserSettings = (): (() => Promise<tsCalendarUserSettings>) => {\n    const api = useApi();\n    const cache = useCache();\n    return useCallback(() => {\n        return getPromiseValue(cache, CalendarUserSettingsModel.key, () => CalendarUserSettingsModel.get(api));\n    }, [cache, api]);\n};\n\nexport const useCalendarUserSettings = (): [tsCalendarUserSettings, boolean, any] => {\n    const cache = useCache();\n    const miss = useGetCalendarUserSettings();\n    return useCachedModelResult(cache, CalendarUserSettingsModel.key, miss);\n};\n","import { useCallback } from 'react';\n\nimport { CalendarWithOwnMembers } from '@proton/shared/lib/interfaces/calendar';\nimport { CalendarsModel } from '@proton/shared/lib/models/calendarsModel';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetCalendars = (): (() => Promise<CalendarWithOwnMembers[] | undefined>) => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => CalendarsModel.get(api), [api]);\n    return useCallback(() => {\n        return getPromiseValue(cache, CalendarsModel.key, miss);\n    }, [cache, miss]);\n};\n\nexport const useCalendars = (): [CalendarWithOwnMembers[] | undefined, boolean, any] => {\n    const cache = useCache();\n    const miss = useGetCalendars();\n    return useCachedModelResult(cache, CalendarsModel.key, miss);\n};\n\nexport default useCalendars;\n","import { useCallback, useMemo } from 'react';\n\nimport { LABEL_TYPE } from '@proton/shared/lib/constants';\nimport { Folder } from '@proton/shared/lib/interfaces/Folder';\nimport { Label } from '@proton/shared/lib/interfaces/Label';\nimport { ContactGroup } from '@proton/shared/lib/interfaces/contacts';\nimport { LabelsModel } from '@proton/shared/lib/models/labelsModel';\n\nimport createUseModelHook from './helpers/createModelHook';\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport { getPromiseValue } from './useCachedModelResult';\n\ntype Category = Folder & Label & ContactGroup;\n\nconst useCategories = createUseModelHook<Category[] | undefined>(LabelsModel);\n\nconst filterCategories = (categories: Category[] | undefined, type: number): Category[] | undefined => {\n    if (!Array.isArray(categories)) {\n        return;\n    }\n    return categories.filter(({ Type }: { Type: number }) => Type === type);\n};\n\nexport const useLabels = (): [Label[] | undefined, boolean] => {\n    const [categories, loading] = useCategories();\n    const labels = useMemo(() => filterCategories(categories, LABEL_TYPE.MESSAGE_LABEL), [categories]);\n    return [labels, loading];\n};\n\nexport const useFolders = (): [Folder[] | undefined, boolean] => {\n    const [categories, loading] = useCategories();\n    const folders = useMemo(() => filterCategories(categories, LABEL_TYPE.MESSAGE_FOLDER), [categories]);\n    return [folders, loading];\n};\n\nexport const useSystemFolders = (): [Label[] | undefined, boolean] => {\n    const [categories, loading] = useCategories();\n    const systemFolders = useMemo(() => filterCategories(categories, LABEL_TYPE.SYSTEM_FOLDER), [categories]);\n    return [systemFolders, loading];\n};\n\nexport const useContactGroups = (): [ContactGroup[] | undefined, boolean] => {\n    const [categories, loading] = useCategories();\n    const contactGroups = useMemo(() => filterCategories(categories, LABEL_TYPE.CONTACT_GROUP), [categories]);\n    return [contactGroups, loading];\n};\n\nconst filterContactGroups = (labels: Label[]) => labels.filter(({ Type }) => Type === LABEL_TYPE.CONTACT_GROUP);\n\nexport const useGetContactGroups = (): (() => Promise<ContactGroup[] | undefined>) => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => LabelsModel.get(api), [api]);\n    return useCallback(() => {\n        return getPromiseValue(cache, LabelsModel.key, miss).then(filterContactGroups);\n    }, [cache, miss]);\n};\n","import { ContactEmailsModel } from '@proton/shared/lib/models/contactEmailsModel';\n\nimport createUseModelHook from './helpers/createModelHook';\n\nexport default createUseModelHook(ContactEmailsModel);\n","import { useEffect } from 'react';\n\nimport {\n    getHasRecoveryMessage,\n    getKeysFromDeviceRecovery,\n    removeDeviceRecovery,\n    storeDeviceRecovery,\n} from '@proton/shared/lib/recoveryFile/deviceRecovery';\nimport arraysContainSameElements from '@proton/utils/arraysContainSameElements';\n\nimport { FeatureCode } from '../../components/containers/features';\nimport useApi from './useApi';\nimport useAuthentication from './useAuthentication';\nimport useFeature from './useFeature';\nimport useIsRecoveryFileAvailable from './useIsRecoveryFileAvailable';\nimport useUser from './useUser';\nimport { useUserKeys } from './useUserKeys';\nimport useUserSettings from './useUserSettings';\n\nexport const useIsDeviceRecoveryEnabled = () => {\n    const [userSettings] = useUserSettings();\n    const authentication = useAuthentication();\n\n    return userSettings.DeviceRecovery && authentication.getTrusted();\n};\n\nexport const useIsDeviceRecoveryAvailable = () => {\n    const trustedDeviceRecoveryFeature = useFeature<boolean>(FeatureCode.TrustedDeviceRecovery);\n    const [recoveryFileAvailable, loading] = useIsRecoveryFileAvailable();\n    return [\n        recoveryFileAvailable && trustedDeviceRecoveryFeature.feature?.Value,\n        loading || trustedDeviceRecoveryFeature.loading,\n    ];\n};\n\nexport const useDeviceRecovery = () => {\n    const [userKeys] = useUserKeys();\n    const [user] = useUser();\n    const api = useApi();\n\n    const [isDeviceRecoveryAvailable] = useIsDeviceRecoveryAvailable();\n    const isDeviceRecoveryEnabled = useIsDeviceRecoveryEnabled();\n    const hasRecoveryMessage = getHasRecoveryMessage(user.ID);\n\n    const privateKeyFingerPrints = userKeys?.map((key) => key.privateKey.getFingerprint()) || [];\n\n    useEffect(() => {\n        let aborted = false;\n        const run = async () => {\n            const shouldRemoveDeviceRecovery = hasRecoveryMessage && !isDeviceRecoveryEnabled;\n            if (shouldRemoveDeviceRecovery) {\n                removeDeviceRecovery(user.ID);\n                return;\n            }\n\n            const shouldStoreDeviceRecovery =\n                isDeviceRecoveryAvailable && (isDeviceRecoveryEnabled || hasRecoveryMessage);\n            if (!privateKeyFingerPrints.length || !shouldStoreDeviceRecovery) {\n                return;\n            }\n\n            const storedKeys = (await getKeysFromDeviceRecovery(user)) || [];\n            if (aborted) {\n                return;\n            }\n            const storedKeyFingerprints = storedKeys.map((key) => key.getFingerprint());\n            const userKeysHaveUpdated = !arraysContainSameElements(storedKeyFingerprints, privateKeyFingerPrints);\n\n            if (!userKeysHaveUpdated || aborted) {\n                return;\n            }\n\n            await storeDeviceRecovery({ api, user, userKeys });\n        };\n\n        void run();\n        return () => {\n            aborted = true;\n        };\n    }, [\n        isDeviceRecoveryAvailable,\n        isDeviceRecoveryEnabled,\n        hasRecoveryMessage,\n        privateKeyFingerPrints.join(''),\n        user.ID,\n    ]);\n};\n","export default function arraysContainSameElements<T>(array1: T[], array2: T[]) {\n    if (array1.length !== array2.length) {\n        return false;\n    }\n\n    return array1.every((element) => array2.includes(element));\n}\n","import { Domain } from '@proton/shared/lib/interfaces';\nimport { DomainsModel } from '@proton/shared/lib/models/domainsModel';\n\nimport createUseModelHook from './helpers/createModelHook';\n\nexport default createUseModelHook<Domain[]>(DomainsModel);\n","import { useCallback } from 'react';\n\nimport { getFullCalendar } from '@proton/shared/lib/api/calendars';\nimport createCache from '@proton/shared/lib/helpers/cache';\nimport { STATUS } from '@proton/shared/lib/models/cache';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const KEY = 'CALENDAR_BOOTSTRAP';\n\nexport const useGetCalendarBootstrap = () => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(\n        (calendarID: string) => {\n            if (!calendarID) {\n                return Promise.resolve();\n            }\n            return api(getFullCalendar(calendarID));\n        },\n        [api]\n    );\n\n    return useCallback(\n        (calendarID: string) => {\n            if (!cache.has(KEY)) {\n                cache.set(KEY, createCache());\n            }\n            return getPromiseValue(cache.get(KEY), calendarID, miss);\n        },\n        [cache, miss]\n    );\n};\n\nexport const useReadCalendarBootstrap = () => {\n    const cache = useCache();\n    return useCallback(\n        (calendarID: string) => {\n            if (!cache.has(KEY)) {\n                cache.set(KEY, createCache());\n            }\n            const oldRecord = cache.get(KEY).get(calendarID);\n            if (!oldRecord || oldRecord.status !== STATUS.RESOLVED) {\n                return;\n            }\n            return oldRecord.value;\n        },\n        [cache]\n    );\n};\n\nexport const useCalendarBootstrap = (calendarID?: string) => {\n    const cache = useCache();\n    const getCalendarBootstrap = useGetCalendarBootstrap();\n    if (!cache.has(KEY)) {\n        cache.set(KEY, createCache());\n    }\n    return useCachedModelResult(cache.get(KEY), calendarID, getCalendarBootstrap);\n};\n\nexport default useGetCalendarBootstrap;\n","import { useCallback } from 'react';\n\nimport { getMemberAndAddress } from '@proton/shared/lib/calendar/members';\nimport { GetCalendarInfo } from '@proton/shared/lib/interfaces/hooks/GetCalendarInfo';\n\nimport { useGetAddresses } from './useAddresses';\nimport { useGetAddressKeys } from './useGetAddressKeys';\nimport { useGetCalendarBootstrap } from './useGetCalendarBootstrap';\nimport { useGetDecryptedPassphraseAndCalendarKeys } from './useGetDecryptedPassphraseAndCalendarKeys';\n\nexport const useGetCalendarInfo = (): GetCalendarInfo => {\n    const getCalendarBootstrap = useGetCalendarBootstrap();\n    const getAddresses = useGetAddresses();\n    const getDecryptedPassphraseAndCalendarKeys = useGetDecryptedPassphraseAndCalendarKeys();\n    const getAddressKeys = useGetAddressKeys();\n\n    return useCallback(\n        async (calendarID: string) => {\n            const [{ Members, CalendarSettings: calendarSettings }, Addresses] = await Promise.all([\n                getCalendarBootstrap(calendarID),\n                getAddresses(),\n            ]);\n\n            const [{ ID: memberID }, { ID: addressID }] = getMemberAndAddress(Addresses, Members);\n\n            const [{ decryptedCalendarKeys, decryptedPassphrase, passphraseID }, addressKeys] = await Promise.all([\n                getDecryptedPassphraseAndCalendarKeys(calendarID),\n                getAddressKeys(addressID),\n            ]);\n\n            return {\n                memberID,\n                addressID,\n                addressKeys,\n                calendarKeys: decryptedCalendarKeys,\n                calendarSettings,\n                passphrase: decryptedPassphrase,\n                passphraseID,\n            };\n        },\n        [getCalendarBootstrap, getAddresses, getDecryptedPassphraseAndCalendarKeys, getAddressKeys]\n    );\n};\n\nexport default useGetCalendarInfo;\n","import { useCallback } from 'react';\n\nimport {\n    decryptPassphrase,\n    decryptPassphraseSessionKey,\n    getDecryptedCalendarKeys,\n} from '@proton/shared/lib/calendar/crypto/keys/calendarKeys';\nimport { getAddressesMembersMap } from '@proton/shared/lib/calendar/crypto/keys/helpers';\nimport { Address } from '@proton/shared/lib/interfaces';\nimport { MemberPassphrase } from '@proton/shared/lib/interfaces/calendar';\nimport { GetAddressKeys } from '@proton/shared/lib/interfaces/hooks/GetAddressKeys';\nimport { GetDecryptedPassphraseAndCalendarKeys } from '@proton/shared/lib/interfaces/hooks/GetDecryptedPassphraseAndCalendarKeys';\nimport { splitKeys } from '@proton/shared/lib/keys';\nimport noop from '@proton/utils/noop';\n\nimport { useGetAddresses } from './useAddresses';\nimport useCache from './useCache';\nimport { getPromiseValue } from './useCachedModelResult';\nimport { useGetAddressKeys } from './useGetAddressKeys';\nimport { useGetCalendarBootstrap } from './useGetCalendarBootstrap';\n\nexport const CACHE_KEY = 'CALENDAR_KEYS';\n\nconst getCalendarKeyPassphrase = async (\n    getAddressKeys: GetAddressKeys,\n    MemberPassphrases: MemberPassphrase[] = [],\n    addressesMembersMap: { [key: string]: Address } = {}\n) => {\n    // Try to decrypt each passphrase with the address keys belonging to that member until it succeeds.\n    for (const { Passphrase, Signature, MemberID } of MemberPassphrases) {\n        const Address = addressesMembersMap[MemberID];\n        if (!Address) {\n            continue;\n        }\n        const addressKeys = await getAddressKeys(Address.ID);\n        const [decryptedPassphrase, decryptedPassphraseSessionKey] = await Promise.all([\n            decryptPassphrase({\n                armoredPassphrase: Passphrase,\n                armoredSignature: Signature,\n                ...splitKeys(addressKeys),\n            }).catch(noop),\n            decryptPassphraseSessionKey({ armoredPassphrase: Passphrase, ...splitKeys(addressKeys) }),\n        ]);\n\n        if (!decryptedPassphrase || !decryptedPassphraseSessionKey) {\n            throw new Error('Error decrypting calendar passphrase');\n        }\n\n        return { decryptedPassphrase, decryptedPassphraseSessionKey };\n    }\n\n    return {};\n};\n\nconst useGetDecryptedPassphraseAndCalendarKeysRaw = () => {\n    const getAddresses = useGetAddresses();\n    const getAddressKeys = useGetAddressKeys();\n    const getCalendarBootstrap = useGetCalendarBootstrap();\n\n    return useCallback(\n        async (calendarID) => {\n            const [{ Keys = [], Passphrase = {}, Members = [] }, Addresses = []] = await Promise.all([\n                getCalendarBootstrap(calendarID),\n                getAddresses(),\n            ]);\n\n            const { ID: PassphraseID, MemberPassphrases } = Passphrase;\n            const addressesMembersMap = getAddressesMembersMap(Members, Addresses);\n            const { decryptedPassphrase, decryptedPassphraseSessionKey } = await getCalendarKeyPassphrase(\n                getAddressKeys,\n                MemberPassphrases,\n                addressesMembersMap\n            );\n\n            if (!decryptedPassphrase || !decryptedPassphraseSessionKey) {\n                throw new Error('No passphrase');\n            }\n\n            return {\n                decryptedCalendarKeys: await getDecryptedCalendarKeys(Keys, { [PassphraseID]: decryptedPassphrase }),\n                decryptedPassphrase,\n                decryptedPassphraseSessionKey,\n                passphraseID: PassphraseID,\n            };\n        },\n        [getAddresses, getAddressKeys, getCalendarBootstrap]\n    );\n};\n\nexport const useGetDecryptedPassphraseAndCalendarKeys = (): GetDecryptedPassphraseAndCalendarKeys => {\n    const cache = useCache();\n    const miss = useGetDecryptedPassphraseAndCalendarKeysRaw();\n\n    return useCallback(\n        (calendarID: string) => {\n            if (!cache.has(CACHE_KEY)) {\n                cache.set(CACHE_KEY, new Map());\n            }\n            const subCache = cache.get(CACHE_KEY);\n            return getPromiseValue(subCache, calendarID, miss);\n        },\n        [cache, miss]\n    );\n};\n\nexport const useGetCalendarKeys = () => {\n    const getDecryptedPassphraseAndCalendarKeys = useGetDecryptedPassphraseAndCalendarKeys();\n\n    return useCallback(\n        async (calendarID: string) => {\n            const { decryptedCalendarKeys } = await getDecryptedPassphraseAndCalendarKeys(calendarID);\n            return decryptedCalendarKeys;\n        },\n        [getDecryptedPassphraseAndCalendarKeys]\n    );\n};\n","import { useCallback } from 'react';\n\nimport { getOrganizationKeys } from '@proton/shared/lib/api/organization';\nimport { OrganizationKey } from '@proton/shared/lib/interfaces';\nimport { getCachedOrganizationKey } from '@proton/shared/lib/keys';\n\nimport useApi from './useApi';\nimport useAuthentication from './useAuthentication';\n\nexport const useGetOrganizationKeyRaw = () => {\n    const authentication = useAuthentication();\n    const api = useApi();\n\n    return useCallback(async () => {\n        const Key = await api<OrganizationKey>(getOrganizationKeys());\n        return getCachedOrganizationKey({ keyPassword: authentication.getPassword(), Key });\n    }, []);\n};\n\nexport default useGetOrganizationKeyRaw;\n","import { getIsMnemonicAvailable } from '../containers/mnemonic/helper';\nimport useAddresses from './useAddresses';\nimport useConfig from './useConfig';\nimport useUser from './useUser';\n\nconst useIsMnemonicAvailable = () => {\n    const { APP_NAME } = useConfig();\n    const [user, loadingUser] = useUser();\n    const [addresses = [], loadingAddresses] = useAddresses();\n\n    const isMnemonicAvailable = getIsMnemonicAvailable({ addresses, user, app: APP_NAME });\n\n    return [isMnemonicAvailable, loadingAddresses || loadingUser] as const;\n};\n\nexport default useIsMnemonicAvailable;\n","import { APPS, APP_NAMES } from '@proton/shared/lib/constants';\nimport { Address, MNEMONIC_STATUS, UserModel } from '@proton/shared/lib/interfaces';\nimport { getHasMigratedAddressKeys } from '@proton/shared/lib/keys';\n\nexport const getIsMnemonicAvailable = ({\n    addresses,\n    user,\n    app,\n}: {\n    addresses: Address[];\n    user: UserModel;\n    app: APP_NAMES;\n}) => {\n    const hasMigratedKeys = getHasMigratedAddressKeys(addresses);\n    const isNonPrivateUser = !user?.isPrivate;\n    return hasMigratedKeys && !isNonPrivateUser && app !== APPS.PROTONVPN_SETTINGS;\n};\n\nexport const getCanReactiveMnemonic = (user: UserModel) => {\n    return (\n        user.MnemonicStatus === MNEMONIC_STATUS.PROMPT ||\n        user.MnemonicStatus === MNEMONIC_STATUS.ENABLED ||\n        user.MnemonicStatus === MNEMONIC_STATUS.OUTDATED\n    );\n};\n","import { getIsRecoveryFileAvailable } from '@proton/shared/lib/recoveryFile/recoveryFile';\n\nimport useAddresses from './useAddresses';\nimport useConfig from './useConfig';\nimport useUser from './useUser';\nimport { useUserKeys } from './useUserKeys';\n\nconst useIsRecoveryFileAvailable = () => {\n    const [user, loadingUser] = useUser();\n    const [addresses = [], loadingAddresses] = useAddresses();\n    const [userKeys = [], loadingUserKeys] = useUserKeys();\n    const { APP_NAME } = useConfig();\n\n    const isRecoveryFileAvailable = getIsRecoveryFileAvailable({\n        user,\n        addresses,\n        userKeys,\n        appName: APP_NAME,\n    });\n\n    return [isRecoveryFileAvailable, loadingUserKeys || loadingAddresses || loadingUser] as const;\n};\n\nexport default useIsRecoveryFileAvailable;\n","import { useEffect, useState } from 'react';\n\nimport useIsMounted from '@proton/hooks/useIsMounted';\nimport { getLastCancelledSubscription } from '@proton/shared/lib/api/payments';\nimport { LatestSubscription } from '@proton/shared/lib/interfaces';\n\nimport useApi from './useApi';\nimport useLoading from './useLoading';\nimport useUser from './useUser';\n\nlet promise: Promise<LatestSubscription> | undefined;\n\nconst useLastSubscriptionEnd = (): [latestSubscription: number, loading: boolean] => {\n    const api = useApi();\n    const [loading, withLoading] = useLoading();\n    const [{ isPaid }] = useUser();\n    const [latestSubscription, setLatestSubscription] = useState<number>(0);\n    const isMounted = useIsMounted();\n\n    useEffect(() => {\n        if (isPaid) {\n            setLatestSubscription(0);\n            return;\n        }\n        const run = async () => {\n            try {\n                if (!promise) {\n                    promise = api<LatestSubscription>(getLastCancelledSubscription());\n                }\n\n                const { LastSubscriptionEnd = 0 } = await promise;\n\n                if (isMounted()) {\n                    setLatestSubscription(LastSubscriptionEnd || 0);\n                }\n            } catch (e) {\n                // Ignore\n            } finally {\n                // Reset promise to allow a new request\n                promise = undefined;\n            }\n        };\n        void withLoading(run());\n    }, [isPaid]);\n\n    return [latestSubscription, loading];\n};\n\nexport default useLastSubscriptionEnd;\n","import { useCallback } from 'react';\n\nimport { MailSettings as tsMailSettings } from '@proton/shared/lib/interfaces';\nimport { MailSettingsModel } from '@proton/shared/lib/models';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetMailSettings = (): (() => Promise<tsMailSettings>) => {\n    const api = useApi();\n    const cache = useCache();\n    return useCallback(() => {\n        return getPromiseValue(cache, MailSettingsModel.key, () => MailSettingsModel.get(api));\n    }, [cache, api]);\n};\n\nexport const useMailSettings = (): [tsMailSettings | undefined, boolean, any] => {\n    const cache = useCache();\n    const miss = useGetMailSettings();\n    return useCachedModelResult(cache, MailSettingsModel.key, miss);\n};\n","import { getAllMemberAddresses } from '@proton/shared/lib/api/members';\nimport { Address, Member, PartialMemberAddress } from '@proton/shared/lib/interfaces';\n\nimport { cachedPromise } from './helpers/cachedPromise';\nimport { useAddresses } from './useAddresses';\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport usePromiseResult from './usePromiseResult';\n\nexport function useMemberAddresses(\n    members: Member[],\n    partial: true\n): [{ [id: string]: PartialMemberAddress[] } | undefined, boolean, any];\nexport function useMemberAddresses(\n    members: Member[],\n    partial?: false\n): [{ [id: string]: Address[] } | undefined, boolean, any];\n\nexport function useMemberAddresses(members: Member[], partial?: boolean) {\n    const cache = useCache();\n    const api = useApi();\n    const [addresses] = useAddresses();\n\n    return usePromiseResult(async () => {\n        if (!Array.isArray(members)) {\n            return;\n        }\n\n        const memberAddresses = await Promise.all(\n            members.map((member) => {\n                const key = `member-addresses-${member.ID}`;\n                if (member.Self) {\n                    return Promise.resolve(addresses);\n                }\n                // Prefer only addresses (partial) from member if the addresses haven't been fetched\n                if (member.Addresses && partial && !cache.has(key)) {\n                    return Promise.resolve(member.Addresses);\n                }\n                return cachedPromise(\n                    cache,\n                    key,\n                    () => {\n                        return getAllMemberAddresses(api, member.ID);\n                    },\n                    member\n                );\n            })\n        );\n\n        return members.reduce<{ [id: string]: Address[] | PartialMemberAddress[] }>((acc, { ID }, i) => {\n            return {\n                ...acc,\n                [ID]: memberAddresses[i],\n            };\n        }, {});\n    }, [members, addresses]);\n}\n","import { useCallback } from 'react';\n\nimport { Member } from '@proton/shared/lib/interfaces';\nimport { MembersModel } from '@proton/shared/lib/models/membersModel';\nimport { UserModel } from '@proton/shared/lib/models/userModel';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult from './useCachedModelResult';\n\nconst useMembers = (): [Member[], boolean, Error] => {\n    const cache = useCache();\n    const api = useApi();\n\n    const miss = useCallback(() => {\n        // Not using use user since it's better to read from the cache\n        // It will be updated from the event manager.\n        const user = cache.get(UserModel.key).value;\n        if (user.isAdmin) {\n            return MembersModel.get(api);\n        }\n        return Promise.resolve([]);\n    }, [api, cache]);\n\n    return useCachedModelResult(cache, MembersModel.key, miss);\n};\n\nexport default useMembers;\n","import { Organization } from '@proton/shared/lib/interfaces';\n\nimport { cachedPromise } from './helpers/cachedPromise';\nimport useCache from './useCache';\nimport { useGetOrganizationKeyRaw } from './useGetOrganizationKeyRaw';\nimport usePromiseResult from './usePromiseResult';\nimport { useUser } from './useUser';\n\nconst useOrganizationKey = (organization?: Organization) => {\n    const cache = useCache();\n    const getOrganizationKeyRaw = useGetOrganizationKeyRaw();\n    const [user] = useUser();\n\n    return usePromiseResult(async () => {\n        if (!user.isAdmin || !organization) {\n            return;\n        }\n        // Warning: There is no event update coming for organization key changes, however, an update for the organization\n        // is received as the keys are changed. So each time it changes, it will redo this.\n        return cachedPromise(\n            cache,\n            'ORGANIZATION_KEY',\n            async () => {\n                return getOrganizationKeyRaw();\n            },\n            organization\n        );\n    }, [user, organization]);\n};\n\nexport default useOrganizationKey;\n","import { useCallback } from 'react';\n\nimport { queryPlans } from '@proton/shared/lib/api/payments';\nimport { Api, Plan } from '@proton/shared/lib/interfaces';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult from './useCachedModelResult';\n\nconst KEY = 'plans';\n\nconst getPlans = (api: Api, Currency?: string) =>\n    api<{ Plans: Plan[] }>(queryPlans({ Currency })).then(({ Plans }) => Plans);\n\n/**\n * Requests available plans information\n */\nconst usePlans = (currency?: string): [Plan[] | undefined, boolean, Error] => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => getPlans(api, currency), [api, currency]);\n    return useCachedModelResult(cache, KEY, miss);\n};\n\nexport default usePlans;\n","import { useCallback } from 'react';\n\nimport { queryPremiumDomains } from '@proton/shared/lib/api/domains';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult from './useCachedModelResult';\n\nconst getPremiumDomains = (api) => api(queryPremiumDomains()).then(({ Domains = [] }) => Domains);\n\nconst usePremiumDomains = () => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => getPremiumDomains(api), [api]);\n    return useCachedModelResult(cache, 'premiumDomains', miss);\n};\n\nexport default usePremiumDomains;\n","import { DependencyList, Reducer, useEffect, useReducer, useRef } from 'react';\n\nimport { STATUS } from '@proton/shared/lib/models/cache';\n\ntype ResolvedRecord<T> = {\n    status: STATUS.RESOLVED;\n    value?: T;\n};\n\ntype PendingRecord<T> = {\n    status: STATUS.PENDING;\n    value?: any;\n    promise?: Promise<T>;\n};\n\ntype RejectedRecord = { status: STATUS.REJECTED; value?: Error };\n\ntype Record<T> = ResolvedRecord<T> | PendingRecord<T> | RejectedRecord;\n\ntype State<T> = [T | undefined, boolean, Error | undefined];\n\nconst getState = <T>(record: Record<T> = { status: STATUS.PENDING }): State<T> => {\n    return [\n        record.status === STATUS.PENDING || record.status === STATUS.RESOLVED ? record.value : undefined,\n        record.status === STATUS.PENDING || record.status === STATUS.REJECTED,\n        record.status === STATUS.REJECTED ? record.value : undefined,\n    ];\n};\n\nconst reducer = <T>(oldValue: State<T>, record: Record<T> = { status: STATUS.PENDING }) => {\n    const newValue = getState(record);\n    if (newValue.every((value, i) => value === oldValue[i])) {\n        return oldValue;\n    }\n    return newValue;\n};\n\n/**\n * The difference with this hook vs `useCachedModelResult` is that this hook does not cache the result in the cache.\n * This hook stores it per component, which means the promise will always be re-run on initial mount.\n */\nconst usePromiseResult = <T>(miss: () => Promise<T>, dependencies: DependencyList) => {\n    const ref = useRef<Record<T>>();\n    const unmountedRef = useRef(false);\n    const [state, dispatch] = useReducer<Reducer<State<T>, Record<T>>, undefined>(reducer, undefined, getState);\n\n    useEffect(() => {\n        return () => {\n            unmountedRef.current = true;\n        };\n    }, []);\n\n    useEffect(() => {\n        const promise = miss();\n\n        const record = {\n            status: STATUS.PENDING,\n            value: ref.current ? ref.current.value : undefined,\n            promise,\n        } as const;\n        ref.current = record;\n        dispatch(record);\n\n        promise\n            .then((value): ResolvedRecord<T> => {\n                return {\n                    status: STATUS.RESOLVED,\n                    value,\n                };\n            })\n            .catch((error): RejectedRecord => {\n                return {\n                    status: STATUS.REJECTED,\n                    value: error,\n                };\n            })\n            .then((record) => {\n                if (unmountedRef.current) {\n                    ref.current = undefined;\n                    return;\n                }\n                const oldRecord = ref.current;\n                // Ensure it's the latest promise that is running\n                if (!oldRecord || ('promise' in oldRecord && oldRecord.promise !== promise)) {\n                    return;\n                }\n                ref.current = record;\n                dispatch(record);\n            });\n    }, dependencies);\n\n    return state;\n};\n\nexport default usePromiseResult;\n","import { getRecoverySecrets } from '@proton/shared/lib/recoveryFile/recoveryFile';\nimport { useUser } from './useUser';\n\nconst useRecoverySecrets = () => {\n    const [{ Keys }] = useUser();\n    return getRecoverySecrets(Keys);\n};\n\nexport default useRecoverySecrets;\n","import { useState } from 'react';\n\nconst useStep = (initialStep = 0) => {\n    const [step, updateStep] = useState(initialStep);\n    const next = () => updateStep((s) => s + 1);\n    const previous = () => updateStep((s) => s - 1);\n    const goTo = (s: number) => updateStep(s);\n\n    return {\n        step,\n        next,\n        previous,\n        goTo,\n    };\n};\n\nexport default useStep;\n","import { useCallback } from 'react';\n\nimport { FREE_SUBSCRIPTION } from '@proton/shared/lib/constants';\nimport { SubscriptionModel as tsSubscriptionModel } from '@proton/shared/lib/interfaces';\nimport { SubscriptionModel } from '@proton/shared/lib/models/subscriptionModel';\nimport { UserModel } from '@proton/shared/lib/models/userModel';\n\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult from './useCachedModelResult';\n\nconst useSubscription = (): [tsSubscriptionModel, boolean, Error] => {\n    const cache = useCache();\n    const api = useApi();\n\n    const miss = useCallback(() => {\n        const { value: user = {} } = cache.get(UserModel.key) || {};\n        if (user.isAdmin && Boolean(user.Subscribed)) {\n            return SubscriptionModel.get(api);\n        }\n        // Member cannot fetch subscription\n        return Promise.resolve(FREE_SUBSCRIPTION);\n    }, [api, cache]);\n\n    return useCachedModelResult(cache, SubscriptionModel.key, miss);\n};\n\nexport default useSubscription;\n","import { useEffect, useState } from 'react';\n\nconst useToggle = (initialState = false) => {\n    const [state, setState] = useState(initialState);\n    const toggle = () => setState(!state);\n\n    useEffect(() => {\n        setState(initialState);\n    }, [initialState]);\n\n    return {\n        state,\n        toggle,\n        set: setState,\n    };\n};\n\nexport default useToggle;\n","import useInstance from '@proton/hooks/useInstance';\nimport generateUID from '@proton/shared/lib/helpers/generateUID';\n\n/* Persists same uid accross component lifetime. */\nconst useUid = (prefix?: string) => {\n    return useInstance(() => generateUID(prefix));\n};\n\nexport default useUid;\n","import truncate from '@proton/utils/truncate';\nimport uniqueBy from '@proton/utils/uniqueBy';\n\nimport { MINUTE } from '../constants';\nimport { convertUTCDateTimeToZone, fromUTCDate, getTimezoneOffset, toUTCDate } from '../date/timezone';\nimport { omit } from '../helpers/object';\nimport {\n    NotificationModel,\n    VcalDurationValue,\n    VcalValarmRelativeComponent,\n    VcalVeventComponent,\n} from '../interfaces/calendar';\nimport getAlarmMessageText from './alarms/getAlarmMessageText';\nimport { getValarmTrigger } from './alarms/getValarmTrigger';\nimport { normalizeDurationToUnit } from './alarms/trigger';\nimport { NOTIFICATION_TYPE_API, NOTIFICATION_UNITS, NOTIFICATION_WHEN } from './constants';\nimport { getDisplayTitle } from './helper';\nimport { getMillisecondsFromTriggerString } from './vcal';\nimport { propertyToUTCDate } from './vcalConverter';\nimport { getIsAllDay } from './vcalHelper';\n\n/**\n * Given a raw event, (optionally) its starting date, the date now and a timezone id,\n * generate a notification message for the event\n */\ninterface Arguments {\n    component: VcalVeventComponent;\n    start?: Date;\n    now: Date;\n    tzid: string;\n    formatOptions: any;\n}\nexport const getAlarmMessage = ({ component, start, now, tzid, formatOptions }: Arguments) => {\n    const { dtstart, summary } = component;\n    const title = truncate(getDisplayTitle(summary?.value), 100);\n    const utcStartDate = start || propertyToUTCDate(dtstart);\n\n    // To determine if the event is happening in timezoned today, tomorrow, this month or this year,\n    // we pass fake UTC dates to the getAlarmMessage helper\n    const startFakeUTCDate = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcStartDate), tzid));\n    const nowFakeUTCDate = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(now), tzid));\n    const isAllDay = getIsAllDay(component);\n\n    return getAlarmMessageText({\n        title,\n        isAllDay,\n        startFakeUTCDate,\n        nowFakeUTCDate,\n        formatOptions,\n    });\n};\n\n/**\n * Given the UNIX timestamp for the occurrence of an alarm, and the trigger string of this alarm,\n * return the timestamp in milliseconds the occurrence of the corresponding event.\n * The computation must take into account possible DST shifts\n */\ninterface Params {\n    Occurrence: number;\n    Trigger: string;\n    tzid: string;\n}\nexport const getNextEventTime = ({ Occurrence, Trigger, tzid }: Params) => {\n    const alarmTime = Occurrence * 1000;\n    const eventTime = alarmTime - getMillisecondsFromTriggerString(Trigger);\n    const offsetAlarmTime = getTimezoneOffset(new Date(alarmTime), tzid).offset;\n    const offsetEventTime = getTimezoneOffset(new Date(eventTime), tzid).offset;\n    const offsetDifference = offsetAlarmTime - offsetEventTime;\n    // correct eventTime in case we jumped across an odd number of DST changes\n    return eventTime - offsetDifference * MINUTE;\n};\n\n/**\n * Filter out future notifications\n */\nexport const filterFutureNotifications = (notifications: NotificationModel[]) => {\n    return notifications.filter(({ when, value }) => {\n        if (when === NOTIFICATION_WHEN.BEFORE) {\n            return true;\n        }\n        return value === 0;\n    });\n};\n\nexport const sortNotificationsByAscendingTrigger = (notifications: NotificationModel[]) =>\n    [...notifications].sort((a: NotificationModel, b: NotificationModel) => {\n        const triggerA = getValarmTrigger(a);\n        const triggerB = getValarmTrigger(b);\n        const triggerAMinutes =\n            normalizeDurationToUnit(triggerA, NOTIFICATION_UNITS.MINUTE) * (triggerA.isNegative ? -1 : 1);\n        const triggerBMinutes =\n            normalizeDurationToUnit(triggerB, NOTIFICATION_UNITS.MINUTE) * (triggerB.isNegative ? -1 : 1);\n\n        return triggerAMinutes - triggerBMinutes;\n    });\n\nconst sortNotificationsByAscendingValue = (a: NotificationModel, b: NotificationModel) =>\n    (a.value || 0) - (b.value || 0);\n\nconst uniqueNotificationComparator = (notification: NotificationModel) => {\n    const trigger = getValarmTrigger(notification);\n\n    return `${notification.type}-${\n        normalizeDurationToUnit(trigger, NOTIFICATION_UNITS.MINUTE) * (trigger.isNegative ? -1 : 1)\n    }`;\n};\n\nexport const dedupeNotifications = (notifications: NotificationModel[]) => {\n    const sortedNotifications = [...notifications].sort(sortNotificationsByAscendingValue);\n\n    return uniqueBy(sortedNotifications, uniqueNotificationComparator);\n};\n\nconst getSmallestNonZeroNumericValueFromDurationValue = (object: VcalDurationValue) =>\n    Math.min(...Object.values(omit(object, ['isNegative'])).filter(Boolean));\n\nconst sortAlarmsByAscendingTriggerValue = (a: VcalValarmRelativeComponent, b: VcalValarmRelativeComponent) => {\n    const aMin = getSmallestNonZeroNumericValueFromDurationValue(a.trigger.value);\n    const bMin = getSmallestNonZeroNumericValueFromDurationValue(b.trigger.value);\n\n    return aMin - bMin;\n};\n\nconst uniqueAlarmComparator = (alarm: VcalValarmRelativeComponent) => {\n    const triggerValue = alarm.trigger.value;\n    const isTriggerNegative = 'isNegative' in triggerValue && triggerValue.isNegative;\n\n    return `${alarm.action.value}-${\n        normalizeDurationToUnit(triggerValue, NOTIFICATION_UNITS.MINUTE) * (isTriggerNegative ? -1 : 1)\n    }`;\n};\n\n/*\n * ATTENTION\n * This function will deduplicate alarms with any type of relative trigger,\n * but if you expect it to pick the nicest triggers (i.e. 2 days instead of 1 day and 24 hours)\n * you must pass normalized triggers\n */\nexport const dedupeAlarmsWithNormalizedTriggers = (alarms: VcalValarmRelativeComponent[]) => {\n    const sortedAlarms = [...alarms].sort(sortAlarmsByAscendingTriggerValue);\n\n    return uniqueBy(sortedAlarms, uniqueAlarmComparator);\n};\n\nexport const isEmailNotification = ({ type }: NotificationModel) => type === NOTIFICATION_TYPE_API.EMAIL;\n","import { NotificationModel } from '../../interfaces/calendar/Notification';\nimport { NOTIFICATION_UNITS, NOTIFICATION_WHEN } from '../constants';\nimport { transformBeforeAt } from './trigger';\n\nconst getValarmTriggerUnit = (unit: NOTIFICATION_UNITS) => {\n    return (\n        {\n            [NOTIFICATION_UNITS.WEEK]: 'weeks',\n            [NOTIFICATION_UNITS.DAY]: 'days',\n            [NOTIFICATION_UNITS.HOUR]: 'hours',\n            [NOTIFICATION_UNITS.MINUTE]: 'minutes',\n        }[unit] || 'days'\n    );\n};\n\nconst getAllDayValarmTrigger = ({\n    isNegative,\n    unit,\n    value = 0,\n    at,\n}: {\n    isNegative: boolean;\n    unit: NOTIFICATION_UNITS;\n    value?: number;\n    at: Date;\n}) => {\n    const modifiedAt = isNegative ? transformBeforeAt(at) : at;\n\n    const hours = modifiedAt.getHours();\n    const minutes = modifiedAt.getMinutes();\n\n    const modifyNegativeDay = isNegative && (minutes > 0 || hours > 0);\n\n    const [weeks, days] = (() => {\n        const weeksValue = unit === NOTIFICATION_UNITS.WEEK ? value : 0;\n        const daysValue = unit === NOTIFICATION_UNITS.DAY ? value : 0;\n\n        if (modifyNegativeDay && weeksValue === 0) {\n            return [0, daysValue - 1];\n        }\n        if (modifyNegativeDay && weeksValue >= 1) {\n            return [weeksValue - 1, 6];\n        }\n        return [weeksValue, daysValue];\n    })();\n\n    return {\n        weeks: Math.max(0, weeks),\n        days: Math.max(0, days),\n        hours,\n        minutes,\n        seconds: 0,\n        isNegative,\n    };\n};\n\nconst getPartDayValarmTrigger = ({\n    isNegative,\n    unit,\n    value = 0,\n}: {\n    isNegative: boolean;\n    unit: NOTIFICATION_UNITS;\n    value?: number;\n}) => {\n    return {\n        weeks: 0,\n        days: 0,\n        hours: 0,\n        minutes: 0,\n        seconds: 0,\n        [getValarmTriggerUnit(unit)]: value,\n        isNegative,\n    };\n};\n\nexport const getValarmTrigger = ({ isAllDay, unit, when, value, at }: NotificationModel) => {\n    const isNegative = when === NOTIFICATION_WHEN.BEFORE;\n    if (isAllDay) {\n        if (!at) {\n            throw new Error('Missing at');\n        }\n        return getAllDayValarmTrigger({ isNegative, unit, value, at });\n    }\n    return getPartDayValarmTrigger({ isNegative, unit, value });\n};\n","import { NotificationModel, VcalDurationValue } from '../../interfaces/calendar';\nimport { normalizeRelativeTrigger, transformBeforeAt } from '../alarms/trigger';\nimport { NOTIFICATION_TYPE_API, NOTIFICATION_UNITS, NOTIFICATION_WHEN } from '../constants';\n\nconst getInt = (value: any) => parseInt(value, 10) || 0;\n\ninterface TriggerToModelShared {\n    when: NOTIFICATION_WHEN;\n    type: NOTIFICATION_TYPE_API;\n    weeks: number;\n    days: number;\n    hours: number;\n    minutes: number;\n}\n\nconst allDayTriggerToModel = ({ type, when, weeks, days, hours, minutes }: TriggerToModelShared) => {\n    const isNegative = when === NOTIFICATION_WHEN.BEFORE;\n\n    const at = new Date(2000, 0, 1, hours, minutes);\n    const modifiedAt = isNegative ? transformBeforeAt(at) : at;\n    const modifyNegativeDay = isNegative && (modifiedAt.getHours() > 0 || modifiedAt.getMinutes() > 0);\n\n    const [value, unit] = (() => {\n        // Transform for example -P1W6DT10H10M into 2 weeks at...\n        if (weeks >= 0 && days === 6 && modifyNegativeDay) {\n            return [weeks + 1, NOTIFICATION_UNITS.WEEK];\n        }\n        // Otherwise, if there is something in the week, and even if there are days in the trigger, the client will truncate this into a week notification since the selector is not more advanced than that.\n        if (weeks > 0) {\n            return [weeks, NOTIFICATION_UNITS.WEEK];\n        }\n        // Finally just return it as a day notification.\n        return [days + +modifyNegativeDay, NOTIFICATION_UNITS.DAY];\n    })();\n\n    return {\n        unit,\n        type,\n        when,\n        value,\n        at: modifiedAt,\n        isAllDay: true,\n    };\n};\n\nconst partDayTriggerToModel = ({ type, when, weeks, days, hours, minutes }: TriggerToModelShared) => {\n    const [value, unit] = (() => {\n        if (weeks) {\n            return [weeks, NOTIFICATION_UNITS.WEEK];\n        }\n        if (days) {\n            return [days, NOTIFICATION_UNITS.DAY];\n        }\n        if (hours) {\n     