\nexport const getIsAddressDisabled = (address: Address) => {\n    return address.Status === ADDRESS_STATUS.STATUS_DISABLED;\n};\n\nexport const getIsAddressActive = (address: Address) => {\n    return (\n        address.Status === ADDRESS_STATUS.STATUS_ENABLED &&\n        address.Receive === ADDRESS_RECEIVE.RECEIVE_YES &&\n        address.Send === ADDRESS_SEND.SEND_YES\n    );\n};\n\nexport const getActiveAddresses = (addresses: Address[]): Address[] => {\n    return addresses.filter(unary(getIsAddressActive));\n};\n\nexport const hasAddresses = (addresses: Address[] | undefined): boolean => {\n    return Array.isArray(addresses) && addresses.length > 0;\n};\n\nexport const getIsAddressExternal = ({ Type }: Address) => {\n    return Type === ADDRESS_TYPE.TYPE_EXTERNAL;\n};\n\nexport const getHasOnlyExternalAddresses = (addresses: Address[]) => {\n    return addresses.length >= 1 && addresses.every((address) => getIsAddressExternal(address));\n};\n\nexport const contactToRecipient = (contact: Partial<ContactEmail> = {}, groupPath?: string): Partial<Recipient> => ({\n    Name: contact.Name,\n    Address: contact.Email,\n    ContactID: contact.ContactID,\n    Group: groupPath,\n});\n\nexport const findUserAddress = (userEmail?: string, addresses: Address[] = []) => {\n    if (!userEmail) {\n        return undefined;\n    }\n    const canonicalUserEmail = canonicalizeInternalEmail(userEmail);\n    return addresses.find(({ Email }) => canonicalizeInternalEmail(Email) === canonicalUserEmail);\n};\n\nexport const getSelfSendAddresses = (ownAddresses: Address[]) => {\n    // For custom domains, Proton Mail allows to have multiple sub-users with the same email address\n    // as long as only one of them is enabled. This poses problems when a sub-user\n    // with a disabled address wants to send email to the same address enabled in another sub-user.\n    // Because of this case, it's better to consider disabled addresses as non self\n    return ownAddresses.filter(({ Receive }) => !!Receive);\n};\n\nexport const getPrimaryAddress = (addresses: Address[]) => {\n    const [address] = getActiveAddresses(addresses);\n\n    if (!address) {\n        throw new Error('No primary address');\n    }\n\n    return address;\n};\n","import orderBy from '@proton/utils/orderBy';\nimport range from '@proton/utils/range';\n\nimport { ROOT_FOLDER } from '../constants';\nimport { Folder, FolderWithSubFolders } from '../interfaces/Folder';\n\nexport const order = (folders: Folder[] = []) => orderBy(folders, 'Order');\n\nexport const getParents = (folders: Folder[] = []) => {\n    return folders.reduce<{ [key: string]: Folder[] }>((acc, item) => {\n        const { ParentID = ROOT_FOLDER } = item;\n        acc[ParentID] = acc[ParentID] || [];\n        acc[ParentID].push(item);\n        return acc;\n    }, {});\n};\n\nexport const buildTreeview = (folders: FolderWithSubFolders[] = []) => {\n    const parents = getParents(folders);\n    const build = (parentID: string | number = ROOT_FOLDER): FolderWithSubFolders[] => {\n        if (!Array.isArray(parents[parentID])) {\n            return [];\n        }\n        return order(parents[parentID]).map((item) => ({\n            ...item,\n            subfolders: build(item.ID),\n        }));\n    };\n    return build();\n};\n\nexport const formatFolderName = (time = 0, name = '', separator = ' ') =>\n    `${range(0, time)\n        .map(() => separator)\n        .join('')}${name}`;\n","let current = 0;\n\nconst generateUID = (prefix?: string) => `${prefix || 'id'}-${current++}`;\n\nexport default generateUID;\n","import { ORGANIZATION_FLAGS } from '../constants';\nimport { Organization } from '../interfaces';\nimport { hasBit } from './bitset';\n\nexport const isLoyal = (organization: Partial<Organization> = {}) => {\n    return hasBit(organization.Flags, ORGANIZATION_FLAGS.LOYAL);\n};\n\nexport const hasCovid = (organization: Partial<Organization> = {}) => {\n    return hasBit(organization.Flags, ORGANIZATION_FLAGS.COVID);\n};\n\nexport const hasSMTPSubmission = (organization: Partial<Organization> = {}) => {\n    return hasBit(organization.Flags, ORGANIZATION_FLAGS.SMTP_SUBMISSION);\n};\n\nexport const isDissident = (organization: Partial<Organization> = {}) => {\n    return hasBit(organization.Flags, ORGANIZATION_FLAGS.DISSIDENT);\n};\n\nexport const hasNoCycleScheduled = (organization: Partial<Organization> = {}) => {\n    return hasBit(organization.Flags, ORGANIZATION_FLAGS.NO_CYCLE_SCHEDULED);\n};\n\nexport const isProtoneer = (organization: Partial<Organization> = {}) => {\n    return hasBit(organization.Flags, ORGANIZATION_FLAGS.PROTON);\n};\n\nexport const hasBonuses = (organization: Partial<Organization> = {}) => {\n    return !!organization.Flags || !!organization.LoyaltyCounter;\n};\n\nexport const humanReadableFlags = (organization: Partial<Organization> = {}) => {\n    let flags = [];\n\n    if (isLoyal(organization)) {\n        flags.push('Loyal');\n    }\n    if (hasCovid(organization)) {\n        flags.push('Covid');\n    }\n    if (hasSMTPSubmission(organization)) {\n        flags.push('SMTP Submission');\n    }\n    if (isDissident(organization)) {\n        flags.push('Dissident');\n    }\n    if (hasNoCycleScheduled(organization)) {\n        flags.push('No Cycle Scheduled');\n    }\n    if (isProtoneer(organization)) {\n        flags.push('Proton');\n    }\n\n    return flags.length > 0 ? flags.join(', ') : '-';\n};\n\nexport const hasFlag = (organization: Partial<Organization> = {}, mask: number) => {\n    return hasBit(Number(organization.Flags), Number(mask));\n};\n","export const escapeRegex = (string: string) => {\n    return string.replace(/[-/\\\\^$*+?.()|[\\]{}]/g, '\\\\$&');\n};\n\nexport interface MatchChunk {\n    start: number;\n    end: number;\n}\n\nexport const getMatches = (regex: RegExp, b: string): MatchChunk[] => {\n    return [...b.matchAll(regex)].map((match) => {\n        const { index = 0 } = match;\n        return {\n            start: index,\n            end: index + match[0].length,\n        };\n    });\n};\n","import { format as formatDate, fromUnixTime, getUnixTime, isSameDay } from 'date-fns';\n\nimport { serverTime } from '@proton/crypto';\n\nexport type DateFnsOptions = Parameters<typeof formatDate>[2];\n\nexport type Options = DateFnsOptions & {\n    /**\n     * Date format if `unixTime` argument is today. If false then force `format`. 'p' by default.\n     */\n    sameDayFormat?: string | false;\n    /**\n     * Date format in general case. 'PP' by default.\n     */\n    format?: string;\n};\n\n/**\n * Convert UNIX timestamp into a readable time. The format of the readable time is:\n * ** Hours and minutes if the UNIX timestamp is from the same day,\n * ** Day, month and year otherwise\n */\nexport const readableTime = (unixTime: number, options: Options = {}) => {\n    let { sameDayFormat, format, ...dateFnsOptions } = options;\n    sameDayFormat = sameDayFormat ?? 'p';\n    format = format ?? 'PP';\n\n    const date = fromUnixTime(unixTime);\n\n    if (sameDayFormat && isSameDay(date, Date.now())) {\n        return formatDate(date, sameDayFormat, dateFnsOptions);\n    }\n\n    return formatDate(date, format, dateFnsOptions);\n};\n\nexport const getCurrentUnixTimestamp = () => {\n    return getUnixTime(serverTime());\n};\n","import { VisualCalendar } from './Calendar';\n\nexport enum CALENDAR_SUBSCRIPTION_STATUS {\n    OK = 0,\n    ERROR = 1,\n    INVALID_ICS = 2,\n    CALENDAR_SOFT_DELETED = 3,\n    CALENDAR_NOT_FOUND = 4,\n    USER_NOT_EXIST = 5,\n    ICS_SIZE_EXCEED_LIMIT = 6,\n    SYNCHRONIZING = 7,\n    CALENDAR_MISSING_PRIMARY_KEY = 8,\n    HTTP_REQUEST_FAILED_GENERIC = 20,\n    HTTP_REQUEST_FAILED_BAD_REQUEST = 21,\n    HTTP_REQUEST_FAILED_UNAUTHORIZED = 22,\n    HTTP_REQUEST_FAILED_FORBIDDEN = 23,\n    HTTP_REQUEST_FAILED_NOT_FOUND = 24,\n    HTTP_REQUEST_FAILED_INTERNAL_SERVER_ERROR = 25,\n    HTTP_REQUEST_FAILED_TIMEOUT = 26,\n    INTERNAL_CALENDAR_URL_NOT_FOUND = 27,\n    INTERNAL_CALENDAR_UNDECRYPTABLE = 28,\n    INVALID_URL = 30,\n}\n\nexport interface CalendarSubscription {\n    CalendarID: string;\n    CreateTime: number;\n    LastUpdateTime: number;\n    Status: CALENDAR_SUBSCRIPTION_STATUS;\n    URL: string;\n}\n\nexport interface SubscribedCalendar extends VisualCalendar {\n    SubscriptionParameters: CalendarSubscription;\n}\n\nexport interface CalendarSubscriptionResponse {\n    CalendarSubscription: CalendarSubscription;\n    Code: number;\n}\n","import { AlgorithmInfo } from '@proton/crypto';\nimport capitalize from '@proton/utils/capitalize';\nimport unique from '@proton/utils/unique';\n\nimport { EncryptionConfig, SimpleMap } from '../interfaces';\n\nconst CUSTOM_FORMATTED_ALGS: SimpleMap<string> = { elgamal: 'ElGamal' };\nconst ECC_ALGS = new Set(['ecdh', 'ecdsa', 'eddsa']);\n\nexport const isRSA = (algorithmName = '') => algorithmName.toLowerCase().startsWith('rsa');\nexport const isECC = (algorithmName = '') => ECC_ALGS.has(algorithmName.toLowerCase());\n\nexport const getFormattedAlgorithmName = ({ algorithm = '', bits, curve }: AlgorithmInfo = { algorithm: '' }) => {\n    // For RSA keys, the algorithm is one of 'rsaEncrypt', 'rsaSign' or 'rsaEncryptSign', for historical reason. We simply display 'RSA'.\n    const name = isRSA(algorithm) ? 'rsa' : algorithm;\n\n    if (isECC(name)) {\n        // Keys using curve 25519 have different curve names (ed25519 or curve25519), which we unify under 'Curve25519'\n        return `ECC (${capitalize(curve === 'ed25519' ? 'curve25519' : curve)})`;\n    }\n\n    const formattedName = CUSTOM_FORMATTED_ALGS[name] || name.toUpperCase();\n\n    return `${formattedName} (${bits})`;\n};\n\n/**\n * Aggregate different algorithm information, returning a string including the list of unique key algo descriptors.\n * @param {AlgorithmInfo[]} algorithmInfos\n * @returns {String} formatted unique algorithm names. Different curves or key sizes result in separate entries, e.g.\n *      [{ name: 'rsa', bits: 2048 }, { name: 'rsa', bits: 4096 }] returns `RSA (2048), RSA (4096)`.\n */\nexport const getFormattedAlgorithmNames = (algorithmInfos: AlgorithmInfo[] = []) => {\n    const formattedAlgos = algorithmInfos.map(getFormattedAlgorithmName);\n    return unique(formattedAlgos).join(', ');\n};\n\nexport const getAlgorithmExists = (algorithmInfos: AlgorithmInfo[] = [], encryptionConfig: EncryptionConfig) => {\n    return algorithmInfos.some(({ algorithm, curve, bits }) => {\n        if (isECC(algorithm)) {\n            return curve === encryptionConfig.curve;\n        }\n\n        if (isRSA(algorithm)) {\n            return bits === encryptionConfig.rsaBits;\n        }\n\n        return false;\n    });\n};\n","import { CryptoProxy, KeyInfo } from '@proton/crypto';\nimport isTruthy from '@proton/utils/isTruthy';\n\nimport { readFileAsString } from '../helpers/file';\n\nexport interface ArmoredKeyWithInfo extends KeyInfo {\n    /**\n     * Armored key corresponding to the key info.\n     * This could be a decrypted private key (see `this.keyIsDecrypted`), so handle with care.\n     */\n    armoredKey: string;\n}\n\nconst ARMORED_KEY_EXPR =\n    /-----BEGIN PGP (PRIVATE|PUBLIC) KEY BLOCK-----(?:(?!-----)[\\s\\S])*-----END PGP (PRIVATE|PUBLIC) KEY BLOCK-----/g;\n\nexport const parseArmoredKeys = (fileString: string) => {\n    return fileString.match(ARMORED_KEY_EXPR) || [];\n};\n\nexport const parseKeys = (filesAsStrings: string[] = []) => {\n    const armoredKeys = parseArmoredKeys(filesAsStrings.join('\\n'));\n    if (!armoredKeys.length) {\n        return [];\n    }\n\n    return Promise.all(\n        armoredKeys.map(async (armoredKey) => {\n            try {\n                const keyInfo = await CryptoProxy.getKeyInfo({ armoredKey });\n                const ArmoredKeyWithInfo = {\n                    ...keyInfo,\n                    armoredKey,\n                };\n                return ArmoredKeyWithInfo;\n            } catch (e: any) {\n                // ignore errors\n            }\n        })\n    ).then((result) => result.filter<ArmoredKeyWithInfo>(isTruthy));\n};\n\nexport const parseKeyFiles = async (files: File[] = []) => {\n    const filesAsStrings = await Promise.all(files.map((file) => readFileAsString(file))).catch(() => []);\n    return parseKeys(filesAsStrings);\n};\n","import { CryptoProxy, PrivateKeyReference } from '@proton/crypto';\nimport { getDefaultKeyFlags } from '@proton/shared/lib/keys/keyFlags';\n\nimport { createMemberKeyRoute, setupMemberKeyRoute } from '../api/memberKeys';\nimport { MEMBER_PRIVATE } from '../constants';\nimport {\n    Api,\n    DecryptedKey,\n    EncryptionConfig,\n    Address as tsAddress,\n    Key as tsKey,\n    Member as tsMember,\n} from '../interfaces';\nimport { srpVerify } from '../srp';\nimport { generateAddressKey, generateAddressKeyTokens } from './addressKeys';\nimport { getActiveKeyObject, getActiveKeys, getNormalizedActiveKeys, getPrimaryFlag } from './getActiveKeys';\nimport { getHasMemberMigratedAddressKeys } from './keyMigration';\nimport { generateKeySaltAndPassphrase } from './keys';\nimport { decryptMemberToken, encryptMemberToken, generateMemberToken } from './memberToken';\nimport { generateMemberAddressKey } from './organizationKeys';\nimport { getSignedKeyList } from './signedKeyList';\nimport { generateUserKey } from './userKeys';\n\nexport const getDecryptedMemberKey = async ({ Token, PrivateKey }: tsKey, organizationKey: PrivateKeyReference) => {\n    if (!Token) {\n        throw new Error('Member token invalid');\n    }\n    const decryptedToken = await decryptMemberToken(Token, [organizationKey], [organizationKey]);\n    return CryptoProxy.importPrivateKey({ armoredKey: PrivateKey, passphrase: decryptedToken });\n};\n\ninterface SetupMemberKeySharedArguments {\n    api: Api;\n    member: tsMember;\n    memberAddresses: tsAddress[];\n    password: string;\n    organizationKey: PrivateKeyReference;\n    encryptionConfig: EncryptionConfig;\n}\n\nexport const setupMemberKeyLegacy = async ({\n    api,\n    member,\n    memberAddresses,\n    password,\n    organizationKey,\n    encryptionConfig,\n}: SetupMemberKeySharedArguments) => {\n    const { salt: keySalt, passphrase: memberMailboxPassword } = await generateKeySaltAndPassphrase(password);\n\n    const AddressKeys = await Promise.all(\n        memberAddresses.map(async (address) => {\n            const { privateKey, privateKeyArmored } = await generateAddressKey({\n                email: address.Email,\n                passphrase: memberMailboxPassword,\n                encryptionConfig,\n            });\n\n            const memberKeyToken = generateMemberToken();\n            const privateKeyArmoredOrganization = await CryptoProxy.exportPrivateKey({\n                privateKey,\n                passphrase: memberKeyToken,\n            });\n            const organizationToken = await encryptMemberToken(memberKeyToken, organizationKey);\n\n            const newActiveKey = await getActiveKeyObject(privateKey, {\n                ID: 'tmp',\n                primary: 1,\n                flags: getDefaultKeyFlags(address),\n            });\n            const updatedActiveKeys = getNormalizedActiveKeys(address, [newActiveKey]);\n            const SignedKeyList = await getSignedKeyList(updatedActiveKeys);\n\n            return {\n                AddressID: address.ID,\n                SignedKeyList,\n                UserKey: privateKeyArmored,\n                MemberKey: privateKeyArmoredOrganization,\n                Token: organizationToken,\n            };\n        })\n    );\n\n    const PrimaryKey = {\n        UserKey: AddressKeys[0].UserKey,\n        MemberKey: AddressKeys[0].MemberKey,\n        Token: AddressKeys[0].Token,\n    };\n\n    await srpVerify({\n        api,\n        credentials: { password },\n        config: setupMemberKeyRoute({\n            MemberID: member.ID,\n            AddressKeys,\n            PrimaryKey,\n            KeySalt: keySalt,\n        }),\n    });\n};\n\nexport const setupMemberKeyV2 = async ({\n    api,\n    member,\n    memberAddresses,\n    password,\n    organizationKey,\n    encryptionConfig,\n}: SetupMemberKeySharedArguments) => {\n    const { salt: keySalt, passphrase: memberKeyPassword } = await generateKeySaltAndPassphrase(password);\n\n    const { privateKey: userPrivateKey, privateKeyArmored: userPrivateKeyArmored } = await generateUserKey({\n        passphrase: memberKeyPassword,\n        encryptionConfig,\n    });\n    const memberKeyToken = generateMemberToken();\n    const privateKeyArmoredOrganization = await CryptoProxy.exportPrivateKey({\n        privateKey: userPrivateKey,\n        passphrase: memberKeyToken,\n    });\n    const organizationToken = await encryptMemberToken(memberKeyToken, organizationKey);\n\n    const AddressKeys = await Promise.all(\n        memberAddresses.map(async (address) => {\n            const { token, signature, organizationSignature, encryptedToken } = await generateAddressKeyTokens(\n                userPrivateKey,\n                organizationKey\n            );\n\n            const { privateKey: addressPrivateKey, privateKeyArmored: addressPrivateKeyArmored } =\n                await generateAddressKey({\n                    email: address.Email,\n                    passphrase: token,\n                    encryptionConfig,\n                });\n\n            const newActiveKey = await getActiveKeyObject(addressPrivateKey, {\n                ID: 'tmp',\n                primary: 1,\n                flags: getDefaultKeyFlags(address),\n            });\n            const updatedActiveKeys = getNormalizedActiveKeys(address, [newActiveKey]);\n            const SignedKeyList = await getSignedKeyList(updatedActiveKeys);\n\n            return {\n                AddressID: address.ID,\n                SignedKeyList,\n                PrivateKey: addressPrivateKeyArmored,\n                Token: encryptedToken,\n                Signature: signature,\n                OrgSignature: organizationSignature,\n            };\n        })\n    );\n\n    await srpVerify({\n        api,\n        credentials: { password },\n        config: setupMemberKeyRoute({\n            MemberID: member.ID,\n            AddressKeys,\n            UserKey: {\n                PrivateKey: userPrivateKeyArmored,\n                OrgPrivateKey: privateKeyArmoredOrganization,\n                OrgToken: organizationToken,\n            },\n            KeySalt: keySalt,\n        }),\n    });\n};\n\nexport const getShouldSetupMemberKeys = (member: tsMember | undefined) => {\n    return !member?.Self && member?.Keys.length === 0 && member.Private === MEMBER_PRIVATE.READABLE;\n};\n\ninterface SetupMemberKeyArguments extends SetupMemberKeySharedArguments {\n    ownerAddresses: tsAddress[];\n}\n\nexport const setupMemberKeys = async ({ ownerAddresses, ...rest }: SetupMemberKeyArguments) => {\n    // During member key setup, no address has keys, so we ignore checking it\n    if (getHasMemberMigratedAddressKeys([], ownerAddresses)) {\n        return setupMemberKeyV2(rest);\n    }\n    return setupMemberKeyLegacy(rest);\n};\n\ninterface CreateMemberAddressKeysLegacyArguments {\n    api: Api;\n    member: tsMember;\n    memberAddress: tsAddress;\n    memberAddressKeys: DecryptedKey[];\n    memberUserKey: PrivateKeyReference;\n    organizationKey: PrivateKeyReference;\n    encryptionConfig: EncryptionConfig;\n}\n\nexport const createMemberAddressKeysLegacy = async ({\n    api,\n    member,\n    memberAddress,\n    memberAddressKeys,\n    memberUserKey,\n    organizationKey,\n    encryptionConfig,\n}: CreateMemberAddressKeysLegacyArguments) => {\n    const { privateKey, activationToken, privateKeyArmored, privateKeyArmoredOrganization, organizationToken } =\n        await generateMemberAddressKey({\n            email: memberAddress.Email,\n            primaryKey: memberUserKey,\n            organizationKey,\n            encryptionConfig,\n        });\n\n    const activeKeys = await getActiveKeys(\n        memberAddress,\n        memberAddress.SignedKeyList,\n        memberAddress.Keys,\n        memberAddressKeys\n    );\n    const newActiveKey = await getActiveKeyObject(privateKey, {\n        ID: 'tmp',\n        primary: getPrimaryFlag(activeKeys),\n        flags: getDefaultKeyFlags(memberAddress),\n    });\n    const updatedActiveKeys = getNormalizedActiveKeys(memberAddress, [...activeKeys, newActiveKey]);\n    const SignedKeyList = await getSignedKeyList(updatedActiveKeys);\n\n    const { primary } = newActiveKey;\n\n    const { MemberKey } = await api(\n        createMemberKeyRoute({\n            MemberID: member.ID,\n            AddressID: memberAddress.ID,\n            Activation: activationToken,\n            UserKey: privateKeyArmored,\n            Token: organizationToken,\n            MemberKey: privateKeyArmoredOrganization,\n            Primary: primary,\n            SignedKeyList,\n        })\n    );\n\n    newActiveKey.ID = MemberKey.ID;\n\n    return updatedActiveKeys;\n};\n\ninterface CreateMemberAddressKeysV2Arguments {\n    api: Api;\n    member: tsMember;\n    memberAddress: tsAddress;\n    memberAddressKeys: DecryptedKey[];\n    memberUserKey: PrivateKeyReference;\n    organizationKey: PrivateKeyReference;\n    encryptionConfig: EncryptionConfig;\n}\n\nexport const createMemberAddressKeysV2 = async ({\n    api,\n    member,\n    memberAddress,\n    memberAddressKeys,\n    memberUserKey,\n    organizationKey,\n    encryptionConfig,\n}: CreateMemberAddressKeysV2Arguments) => {\n    const { token, signature, organizationSignature, encryptedToken } = await generateAddressKeyTokens(\n        memberUserKey,\n        organizationKey\n    );\n\n    const { privateKey: addressPrivateKey, privateKeyArmored: addressPrivateKeyArmored } = await generateAddressKey({\n        email: memberAddress.Email,\n        passphrase: token,\n        encryptionConfig,\n    });\n\n    const activeKeys = await getActiveKeys(\n        memberAddress,\n        memberAddress.SignedKeyList,\n        memberAddress.Keys,\n        memberAddressKeys\n    );\n    const newActiveKey = await getActiveKeyObject(addressPrivateKey, {\n        ID: 'tmp',\n        primary: getPrimaryFlag(activeKeys),\n        flags: getDefaultKeyFlags(memberAddress),\n    });\n    const updatedActiveKeys = getNormalizedActiveKeys(memberAddress, [...activeKeys, newActiveKey]);\n    const SignedKeyList = await getSignedKeyList(updatedActiveKeys);\n\n    const { primary } = newActiveKey;\n\n    const { MemberKey } = await api(\n        createMemberKeyRoute({\n            MemberID: member.ID,\n            AddressID: memberAddress.ID,\n            PrivateKey: addressPrivateKeyArmored,\n            Token: encryptedToken,\n            Signature: signature,\n            OrgSignature: organizationSignature,\n            Primary: primary,\n            SignedKeyList,\n        })\n    );\n\n    newActiveKey.ID = MemberKey.ID;\n\n    return updatedActiveKeys;\n};\n","import { PrivateKeyReference } from '@proton/crypto';\n\nimport { Address, Api, EncryptionConfig, Member } from '../interfaces';\nimport { getHasMemberMigratedAddressKeys } from './keyMigration';\nimport { createMemberAddressKeysLegacy, createMemberAddressKeysV2, getDecryptedMemberKey } from './memberKeys';\n\ntype OnUpdateCallback = (ID: string, update: { status: 'loading' | 'error' | 'ok'; result?: string }) => void;\n\ninterface MissingKeysMemberProcessArguments {\n    api: Api;\n    encryptionConfig: EncryptionConfig;\n    onUpdate: OnUpdateCallback;\n    organizationKey: PrivateKeyReference;\n    ownerAddresses: Address[];\n    member: Member;\n    memberAddresses: Address[];\n    memberAddressesToGenerate: Address[];\n}\n\nexport const missingKeysMemberProcess = async ({\n    api,\n    encryptionConfig,\n    onUpdate,\n    ownerAddresses,\n    member,\n    memberAddresses,\n    memberAddressesToGenerate,\n    organizationKey,\n}: MissingKeysMemberProcessArguments) => {\n    const PrimaryKey = member.Keys.find(({ Primary }) => Primary === 1);\n\n    if (!PrimaryKey) {\n        throw new Error('Member keys are not set up');\n    }\n\n    const hasMigratedAddressKeys = getHasMemberMigratedAddressKeys(memberAddresses, ownerAddresses);\n\n    const primaryMemberUserKey = await getDecryptedMemberKey(PrimaryKey, organizationKey);\n\n    return Promise.all(\n        memberAddressesToGenerate.map(async (memberAddress) => {\n            try {\n                onUpdate(memberAddress.ID, { status: 'loading' });\n\n                if (hasMigratedAddressKeys) {\n                    await createMemberAddressKeysV2({\n                        api,\n                        member,\n                        memberAddress,\n                        memberAddressKeys: [], // Assume no keys exist for this address since we are in this modal.\n                        encryptionConfig,\n                        memberUserKey: primaryMemberUserKey,\n                        organizationKey,\n                    });\n                } else {\n                    await createMemberAddressKeysLegacy({\n                        api,\n                        member,\n                        memberAddress,\n                        memberAddressKeys: [], // Assume no keys exist for this address since we are in this modal.\n                        encryptionConfig,\n                        memberUserKey: primaryMemberUserKey,\n                        organizationKey,\n                    });\n                }\n\n                onUpdate(memberAddress.ID, { status: 'ok' });\n            } catch (e: any) {\n                onUpdate(memberAddress.ID, { status: 'error', result: e.message });\n            }\n        })\n    );\n};\n","import { Address, Api, DecryptedKey, EncryptionConfig } from '../interfaces';\nimport { createAddressKeyLegacy, createAddressKeyV2 } from './add';\nimport { getPrimaryKey } from './getPrimaryKey';\nimport { getHasMigratedAddressKeys } from './keyMigration';\n\ntype OnUpdateCallback = (ID: string, update: { status: 'loading' | 'error' | 'ok'; result?: string }) => void;\n\ninterface MissingKeysSelfProcessArguments {\n    api: Api;\n    userKeys: DecryptedKey[];\n    encryptionConfig: EncryptionConfig;\n    addresses: Address[];\n    addressesToGenerate: Address[];\n    password: string;\n    onUpdate: OnUpdateCallback;\n}\n\nexport const missingKeysSelfProcess = ({\n    api,\n    userKeys,\n    encryptionConfig,\n    addresses,\n    addressesToGenerate,\n    password,\n    onUpdate,\n}: MissingKeysSelfProcessArguments) => {\n    const hasMigratedAddressKeys = getHasMigratedAddressKeys(addresses);\n    const primaryUserKey = getPrimaryKey(userKeys)?.privateKey;\n    if (!primaryUserKey) {\n        throw new Error('Missing primary user key');\n    }\n\n    return Promise.all(\n        addressesToGenerate.map(async (address) => {\n            try {\n                onUpdate(address.ID, { status: 'loading' });\n\n                if (hasMigratedAddressKeys) {\n                    await createAddressKeyV2({\n                        api,\n                        address,\n                        encryptionConfig,\n                        userKey: primaryUserKey,\n                        activeKeys: [],\n                    });\n                } else {\n                    await createAddressKeyLegacy({\n                        api,\n                        address,\n                        encryptionConfig,\n                        passphrase: password,\n                        activeKeys: [],\n                    });\n                }\n\n                onUpdate(address.ID, { status: 'ok' });\n            } catch (e: any) {\n                onUpdate(address.ID, { status: 'error', result: e.message });\n            }\n        })\n    );\n};\n","import { SessionKey } from '@proton/crypto';\n\nimport { AES256 } from '../constants';\nimport { base64StringToUint8Array } from '../helpers/encoding';\n\nexport const toSessionKey = (decryptedKeyPacket: string): SessionKey => {\n    return { algorithm: AES256, data: base64StringToUint8Array(decryptedKeyPacket) };\n};\n","import { Recipient } from '../interfaces';\nimport { ContactEmail } from '../interfaces/contacts';\nimport { unescapeFromString } from '../sanitize/escape';\n\nexport const REGEX_RECIPIENT = /(.*?)\\s*<([^>]*)>/;\n\nexport const inputToRecipient = (input: string) => {\n    // Remove potential unwanted HTML entities such as '&shy;' from the string\n    const cleanInput = unescapeFromString(input);\n    const trimmedInput = cleanInput.trim();\n    const match = REGEX_RECIPIENT.exec(trimmedInput);\n\n    if (match !== null && (match[1] || match[2])) {\n        const trimmedMatches = match.map((match) => match.trim());\n        return {\n            Name: trimmedMatches[1],\n            Address: trimmedMatches[2] || trimmedMatches[1],\n        };\n    }\n    return {\n        Name: trimmedInput,\n        Address: trimmedInput,\n    };\n};\nexport const contactToRecipient = (contact: ContactEmail, groupPath?: string) => ({\n    Name: contact.Name,\n    Address: contact.Email,\n    ContactID: contact.ContactID,\n    Group: groupPath,\n});\n\nexport const majorToRecipient = (email: string) => ({\n    Name: email,\n    Address: email,\n});\n\nexport const recipientToInput = (recipient: Recipient): string => {\n    if (recipient.Address && recipient.Name && recipient.Address !== recipient.Name) {\n        return `${recipient.Name} <${recipient.Address}>`;\n    }\n\n    if (recipient.Address === recipient.Name) {\n        return recipient.Address || '';\n    }\n\n    return `${recipient.Name} ${recipient.Address}`;\n};\n\nexport const contactToInput = (contact: ContactEmail): string => recipientToInput(contactToRecipient(contact));\n","import { c } from 'ttag';\n\nimport { APPS, APPS_CONFIGURATION } from '../constants';\n\ninterface Options {\n    isReferralProgramLinkEnabled?: boolean;\n    referralProgramUserLink?: string;\n}\n\nexport const getProtonMailSignature = ({\n    isReferralProgramLinkEnabled = false,\n    referralProgramUserLink,\n}: Options = {}) => {\n    const link =\n        isReferralProgramLinkEnabled && referralProgramUserLink ? referralProgramUserLink : 'https://proton.me/';\n\n    // translator: full sentence is: \"Sent with Proton Mail secure email\"\n    const signature = c('Info').t`Sent with <a href=\"${link}\" target=\"_blank\">${\n        APPS_CONFIGURATION[APPS.PROTONMAIL].name\n    }</a> secure email.`;\n\n    return signature;\n};\n","import { getCalendarUserSettings } from '../api/calendars';\nimport updateObject from '../helpers/updateObject';\n\nexport const getCalendarUserSettingsModel = (api) => {\n    return api(getCalendarUserSettings()).then(({ CalendarUserSettings }) => CalendarUserSettings);\n};\n\nexport const CalendarUserSettingsModel = {\n    key: 'CalendarUserSettings',\n    get: getCalendarUserSettingsModel,\n    update: updateObject,\n};\n","import { queryCalendars } from '../api/calendars';\nimport updateCollection from '../helpers/updateCollection';\n\nexport const CALENDARS_CACHE_KEY = 'Calendars';\n\nexport const getCalendars = async (api) => {\n    const result = await api(queryCalendars());\n    return result.Calendars;\n};\n\nexport const CalendarsModel = {\n    key: CALENDARS_CACHE_KEY,\n    get: getCalendars,\n    update: (model, events) => {\n        updateCollection({ model, events, itemKey: 'Calendar' });\n    },\n};\n","import { MEMBER_ROLE } from '../constants';\nimport { CachedOrganizationKey, Member, Organization } from '../interfaces';\n\nexport const getHasOtherAdmins = (members: Member[]) =>\n    members.some(({ Role, Self }) => Self !== 1 && Role === MEMBER_ROLE.ORGANIZATION_ADMIN);\n\nexport const getNonPrivateMembers = (members: Member[]) => members.filter(({ Private }) => Private === 0);\n\nexport const getOrganizationKeyInfo = (\n    organization: Organization | undefined,\n    organizationKey?: CachedOrganizationKey\n) => {\n    const organizationHasKeys = !!organization?.HasKeys;\n    // If the user has the organization key (not the organization itself).\n    const userHasActivatedOrganizationKeys = !!organizationKey?.Key?.PrivateKey;\n    return {\n        // If the user does not have the organization key but the organization has keys setup, it's inactive\n        userNeedsToActivateKey: organizationHasKeys && !userHasActivatedOrganizationKeys,\n        // If the user has the organization key, but it's not decrypted. Typically following a password reset\n        userNeedsToReactivateKey:\n            organizationHasKeys && userHasActivatedOrganizationKeys && !organizationKey?.privateKey,\n    };\n};\n","/*\n * This is valid\n * - background:&#117;r&#108;(\n * - background:&#117;r&#108;(\n * - background:url&lpar;\n * - etc.\n */\nconst CSS_URL = '((url|image-set)(\\\\(|&(#40|#x00028|lpar);))';\nconst REGEXP_URL_ATTR = new RegExp(CSS_URL, 'gi');\n\nconst REGEXP_HEIGHT_PERCENTAGE = /((?:min-|max-|line-)?height)\\s*:\\s*([\\d.,]+%)/gi;\nconst REGEXP_POSITION_ABSOLUTE = /position\\s*:\\s*absolute/gi;\nconst REGEXP_MEDIA_DARK_STYLE = /\\(\\s*prefers-color-scheme\\s*:\\s*dark\\s*\\)/gi;\n\nexport const escape = (string: string) => {\n    const UNESCAPE_HTML_REGEX = /[&<>\"']/g;\n    const HTML_ESCAPES = {\n        '&': '&amp;',\n        '<': '&lt;',\n        '>': '&gt;',\n        '\"': '&quot;',\n        \"'\": '&#39;',\n    };\n\n    return string.replace(UNESCAPE_HTML_REGEX, HTML_ESCAPES as any);\n};\n\nexport const unescape = (string: string) => {\n    const ESCAPED_HTML_REGEX = /&(?:amp|lt|gt|quot|#39);/g;\n    const HTML_UNESCAPES = {\n        '&amp;': '&',\n        '&lt;': '<',\n        '&gt;': '>',\n        '&quot;': '\"',\n        '&#39;': \"'\",\n    };\n\n    return string.replace(ESCAPED_HTML_REGEX, HTML_UNESCAPES as any);\n};\n\n/**\n * Unescape a string in hex or octal encoding.\n * See https://www.w3.org/International/questions/qa-escapes#css_other for all possible cases.\n */\nexport const unescapeCSSEncoding = (str: string) => {\n    // Regexp declared inside the function to reset its state (because of the global flag).\n    // cf https://stackoverflow.com/questions/1520800/why-does-a-regexp-with-global-flag-give-wrong-results\n    const UNESCAPE_CSS_ESCAPES_REGEX = /\\\\([0-9A-Fa-f]{1,6}) ?/g;\n    const UNESCAPE_HTML_DEC_REGEX = /&#(\\d+)(;|(?=[^\\d;]))/g;\n    const UNESCAPE_HTML_HEX_REGEX = /&#x([0-9A-Fa-f]+)(;|(?=[^\\d;]))/g;\n    const OTHER_ESC = /\\\\(.)/g;\n\n    const handleEscape = (radix: number) => (ignored: any, val: string) => {\n        try {\n            return String.fromCodePoint(Number.parseInt(val, radix));\n        } catch {\n            // Unescape regexps have some limitations, for those rare situations, fromCodePoint can throw\n            // One real found is: `font-family:\\2018Calibri`\n            return '';\n        }\n    };\n\n    /*\n     * basic unescaped named sequences: &amp; etcetera, lodash does not support a lot, but that is not a problem for our case.\n     * Actually handling all escaped sequences would mean keeping track of a very large and ever growing amount of named sequences\n     */\n    const namedUnescaped = unescape(str);\n    // lodash doesn't unescape &#160; or &#xA0; sequences, we have to do this manually:\n    const decUnescaped = namedUnescaped.replace(UNESCAPE_HTML_DEC_REGEX, handleEscape(10));\n    const hexUnescaped = decUnescaped.replace(UNESCAPE_HTML_HEX_REGEX, handleEscape(16));\n    // unescape css backslash sequences\n    const strUnescapedHex = hexUnescaped.replace(UNESCAPE_CSS_ESCAPES_REGEX, handleEscape(16));\n\n    return strUnescapedHex.replace(OTHER_ESC, (_, char) => char);\n};\n\n/**\n * Input can be escaped multiple times to escape replacement while still works\n * Best solution I found is to escape recursively\n * This is done 5 times maximum. If there are too much escape, we consider the string\n * \"invalid\" and we prefer to return an empty string\n * @argument str style to unescape\n * @augments stop extra security to prevent infinite loop\n */\nexport const recurringUnescapeCSSEncoding = (str: string, stop = 5): string => {\n    const escaped = unescapeCSSEncoding(str);\n    if (escaped === str) {\n        return escaped;\n    } else if (stop === 0) {\n        return '';\n    } else {\n        return recurringUnescapeCSSEncoding(escaped, stop - 1);\n    }\n};\n\n/**\n * Escape some WTF from the CSSParser, cf spec files\n * @param  {String} style\n * @return {String}\n */\nexport const escapeURLinStyle = (style: string) => {\n    // handle the case where the value is html encoded, e.g.:\n    // background:&#117;rl(&quot;https://i.imgur.com/WScAnHr.jpg&quot;)\n\n    const unescapedEncoding = recurringUnescapeCSSEncoding(style);\n    const escapeFlag = unescapedEncoding !== style;\n\n    const escapedStyle = unescapedEncoding.replace(/\\\\r/g, 'r').replace(REGEXP_URL_ATTR, 'proton-$2(');\n\n    if (escapedStyle === unescapedEncoding) {\n        // nothing escaped: just return input\n        return style;\n    }\n\n    return escapeFlag ? escape(escapedStyle) : escapedStyle;\n};\n\nexport const escapeForbiddenStyle = (style: string): string => {\n    let parsedStyle = style\n        .replaceAll(REGEXP_POSITION_ABSOLUTE, 'position: relative')\n        .replaceAll(REGEXP_HEIGHT_PERCENTAGE, (rule, prop) => {\n            // Replace nothing in this case.\n            if (['line-height', 'max-height'].includes(prop)) {\n                return rule;\n            }\n\n            return `${prop}: unset`;\n        })\n        // \"never\" is not a valid value, it's meant to be invalid and break the media query\n        .replaceAll(REGEXP_MEDIA_DARK_STYLE, '(prefers-color-scheme: never)');\n\n    return parsedStyle;\n};\n\nconst HTML_ENTITIES_TO_REMOVE_CHAR_CODES: number[] = [\n    9, // Tab : &Tab; - &#x00009; - &#9;\n    10, // New line : &NewLine; - &#x0000A; - &#10;\n    173, // Soft hyphen : &shy; - &#x000AD; - &#173;\n    8203, // Zero width space : &ZeroWidthSpace; - &NegativeVeryThinSpace; - &NegativeThinSpace; - &NegativeMediumSpace; - &NegativeThickSpace; - &#x0200B; - &#8203;\n];\n\n/**\n * Remove completely some HTML entities from a string\n * @param {String} string\n * @return {String}\n */\nexport const unescapeFromString = (string: string) => {\n    const toRemove = HTML_ENTITIES_TO_REMOVE_CHAR_CODES.map((charCode) => String.fromCharCode(charCode));\n    const regex = new RegExp(toRemove.join('|'), 'g');\n\n    return string.replace(regex, '');\n};\n","import { WeekStartsOn } from '../date-fns-utc/interface';\nimport { browserDateLocale } from '../i18n';\nimport { getIsLocaleAMPM } from '../i18n/dateFnLocale';\nimport { SETTINGS_TIME_FORMAT, SETTINGS_WEEK_START, UserSettings } from '../interfaces';\n\nexport const getDefaultDateFormat = () => {\n    return browserDateLocale.formatLong?.date({ width: 'short' });\n};\n\nexport const getDefaultTimeFormat = () => {\n    const isAMPM = getIsLocaleAMPM(browserDateLocale);\n    return isAMPM ? SETTINGS_TIME_FORMAT.H12 : SETTINGS_TIME_FORMAT.H24;\n};\n\nexport const getDefaultWeekStartsOn = (): WeekStartsOn => {\n    const localeWeekStartsOn = browserDateLocale?.options?.weekStartsOn;\n    if (localeWeekStartsOn !== undefined && localeWeekStartsOn >= 0 && localeWeekStartsOn <= 6) {\n        return localeWeekStartsOn;\n    }\n    return 0;\n};\n\nexport const getWeekStartsOn = ({ WeekStart }: Pick<UserSettings, 'WeekStart'>): WeekStartsOn => {\n    if (WeekStart === SETTINGS_WEEK_START.LOCALE_DEFAULT) {\n        return getDefaultWeekStartsOn();\n    }\n    if (WeekStart >= 1 && WeekStart <= 7) {\n        return (WeekStart % 7) as WeekStartsOn;\n    }\n    return 0;\n};\n","/**\n * Capitalize the first letter in a string.\n */\nexport default function capitalize(str: string | undefined) {\n    if (str === undefined) {\n        return;\n    }\n\n    if (str === '') {\n        return str;\n    }\n    return str[0].toUpperCase() + str.slice(1);\n}\n","/**\n * Returns a new array with the item moved to the new position.\n * @param list List of items\n * @param from Index of item to move. If negative, it will begin that many elements from the end.\n * @param to Index of where to move the item. If negative, it will begin that many elements from the end.\n * @return New array with the item moved to the new position\n */\nconst move = <T>(list: T[] = [], from: number, to: number) => {\n    const copy = list.slice();\n    copy.splice(to < 0 ? copy.length + to : to, 0, copy.splice(from, 1)[0]);\n    return copy;\n};\n\nexport default move;\n","/**\n * Order collection of object by a specific key\n */\nconst orderBy = <T, K extends keyof T>(collection: T[], key: K) => {\n    return collection.slice().sort((a, b) => {\n        if (a[key] > b[key]) {\n            return 1;\n        }\n        if (a[key] < b[key]) {\n            return -1;\n        }\n        return 0;\n    });\n};\n\nexport default orderBy;\n","/**\n * Creates an array of elements split into two groups, the first of which contains elements predicate returns\n * truthy for, the second of which contains elements predicate returns falsey for.\n */\nexport default function partition<T, K = T>(arr: (T | K)[], predicate: (item: T | K) => item is T): [T[], K[]] {\n    const truthyItems: T[] = [];\n    const falseyItems: K[] = [];\n\n    for (const item of arr) {\n        if (predicate(item)) {\n            truthyItems.push(item);\n        } else {\n            falseyItems.push(item);\n        }\n    }\n\n    return [truthyItems, falseyItems];\n}\n","/**\n * Build an array with a numeric range, specified by a start, an end, and a step\n */\nconst range = (start = 0, end = 1, step = 1) => {\n    const result = [];\n    for (let index = start; index < end; index += step) {\n        result.push(index);\n    }\n    return result;\n};\n\nexport default range;\n","export const DEFAULT_TRUNCATE_OMISSION = '…';\n\n/**\n * Truncate `str` to a maximum length `charsToDisplay`.\n * Appends `omission` if `str` is too long.\n *\n * The length of the string returned (which may include\n * the omission) will not exceed `charsToDisplay`.\n */\nexport default function truncate(\n    /**\n     * String to truncate.\n     */\n    str: string,\n    /**\n     * Number of characters to display.\n     */\n    charsToDisplay = 50,\n    /**\n     * The string appended if `str` is too long.\n     */\n    omission = DEFAULT_TRUNCATE_OMISSION\n) {\n    if (str.length === 0 || str.length <= charsToDisplay) {\n        return str;\n    }\n\n    return str.substring(0, charsToDisplay - omission.length) + omission;\n}\n","/**\n * Wrap a function to ensure only one argument will pass through\n */\nexport default function unary<A, B>(fn: (...args: any) => B) {\n    return (arg: A) => fn(arg);\n}\n"],"names":["getHasPmMeAddress","addresses","some","Type","ADDRESS_TYPE","getShowPmMeSection","user","hasPaidMail","canPay","isExternalUser","UserType","isPMAddressActive","hasNoOriginalAddresses","address","getMailAppRoutes","organization","isSpyTrackerEnabled","isShowSenderImagesEnabled","isSmtpTokenEnabled","hasOrganization","HasKeys","isB2BOrganization","MaxMembers","hasSmtpOrganization","hasSMTPSubmission","header","MAIL_APP_NAME","routes","general","text","c","t","to","icon","subsections","id","available","privacy","identity","appearance","folder","description","filter","autoReply","domainNames","isMember","keys","imap","backup","isFree","props","Name","Email","useUser","userSettings","useUserSettings","useAddresses","email","Value","BugModal","username","domain","onSubmit","onEdit","loading","withLoading","useLoading","createYourOwn","className","Card","bordered","rounded","Button","size","color","onClick","catch","noop","fullWidth","shape","undefined","defaultUsername","availableDomains","setUsername","useState","validator","onFormSubmit","useFormErrors","trimmedUsername","trim","length","name","event","preventDefault","method","Inp